            id TEXT PRIMARY KEY, event TEXT NOT NULL, name TEXT NOT NULL, phone TEXT DEFAULT '',
            guests INTEGER DEFAULT 0, ts TEXT DEFAULT (datetime('now')), UNIQUE(event, name))");
        /* V2.31.7: samity committee elections — members elect the committee by voting.
           Elections hold positions (JSON: [{name, seats}]), candidates link samity_members
           to a position, ballots are one row per (election, voter, position). */
        $pdo->exec("CREATE TABLE IF NOT EXISTS samity_elections (
            id TEXT PRIMARY KEY, owner_email TEXT DEFAULT '', title TEXT NOT NULL,
            status TEXT DEFAULT 'draft', positions TEXT NOT NULL DEFAULT '[]',
            starts_at TEXT DEFAULT '', ends_at TEXT DEFAULT '',
            created_by TEXT DEFAULT '', created_name TEXT DEFAULT '',
            closed_at TEXT DEFAULT '', ts TEXT DEFAULT (datetime('now')))");
        $pdo->exec("CREATE INDEX IF NOT EXISTS idx_sel_status ON samity_elections(owner_email, status)");
        $pdo->exec("CREATE TABLE IF NOT EXISTS samity_candidates (
            id TEXT PRIMARY KEY, election TEXT NOT NULL, member TEXT NOT NULL,
            position TEXT NOT NULL, manifesto TEXT DEFAULT '',
            ts TEXT DEFAULT (datetime('now')))");
        $pdo->exec("CREATE INDEX IF NOT EXISTS idx_scd_election ON samity_candidates(election, position)");
        $pdo->exec("CREATE TABLE IF NOT EXISTS samity_ballots (
            id TEXT PRIMARY KEY, election TEXT NOT NULL, voter TEXT NOT NULL,
            position TEXT NOT NULL, candidate TEXT NOT NULL,
            ts TEXT DEFAULT (datetime('now')), UNIQUE(election, voter, position))");
        /* V2.31.5: workspace backup/restore console — JSON snapshots of the
           owner's scoped data (sub_email chain), one row per backup. */
        $pdo->exec("CREATE TABLE IF NOT EXISTS ws_backups (
            id TEXT PRIMARY KEY, sub_email TEXT NOT NULL, kind TEXT DEFAULT 'manual',
            size INTEGER DEFAULT 0, note TEXT DEFAULT '', data TEXT DEFAULT '',
            created_by TEXT DEFAULT '', ts TEXT DEFAULT (datetime('now')))");
        try { $pdo->exec('PRAGMA user_version=20260922'); } catch (Exception $e) {}
        }   /* end schema bootstrap gate */
        /* V2.40 (unconditional): seed templates on every boot — COUNT-guarded
           inserts make it idempotent; needed so NEW template ids (e.g.
           payment_failed) reach already-migrated live DBs. */
        seed_templates($pdo);
        /* ── V2.39 (unconditional): tenant acknowledgment columns on handover checklists ── */
        $hcols = [];
        foreach ($pdo->query('PRAGMA table_info(handover_checklists)') as $c) $hcols[] = $c['name'];
        if (!in_array('acknowledged_by', $hcols, true)) $pdo->exec("ALTER TABLE handover_checklists ADD COLUMN acknowledged_by TEXT DEFAULT ''");
        if (!in_array('acknowledged_at', $hcols, true)) $pdo->exec("ALTER TABLE handover_checklists ADD COLUMN acknowledged_at TEXT DEFAULT ''");
    }
    /* ── V2.39.3 (unconditional): tenant role gains the portal module in Starter/Business matrices ── */
    try {
        foreach (['starter', 'business'] as $cc) {
            $cr = $pdo->prepare('SELECT modules FROM plan_catalog WHERE lower(code)=?'); $cr->execute([$cc]);
            $mraw = $cr->fetchColumn();
            if ($mraw) {
                $mm = json_decode($mraw, true) ?: [];
                if (isset($mm['tenant']) && is_array($mm['tenant']) && !in_array('portal', $mm['tenant'], true)) {
                    $mm['tenant'][] = 'portal';
                    $pdo->prepare('UPDATE plan_catalog SET modules=? WHERE lower(code)=?')->execute([json_encode($mm), $cc]);
                }
            }
        }
    } catch (Exception $e) { /* non-fatal */ }
    /* ── V2.39.4 (unconditional): owner scoping for community + elections ── */
    try {
        foreach (['community_parking', 'community_bookings', 'community_votes', 'community_threads', 'community_events'] as $ct) {
            $ccols = [];
            foreach ($pdo->query("PRAGMA table_info($ct)") as $c) $ccols[] = $c['name'];
            if (!in_array('owner_email', $ccols, true)) $pdo->exec("ALTER TABLE $ct ADD COLUMN owner_email TEXT DEFAULT ''");
        }
    } catch (Exception $e) { /* non-fatal */ }
    return $pdo;
}

function audit($user, $action, $module, $entity, $details = '') {
    $pdo = db();
    $pdo->prepare('INSERT INTO audit_log (user, action, module, entity, details) VALUES (?,?,?,?,?)')
        ->execute([$user, $action, $module, $entity, $details]);
}

/* ---------- Phase 6: auth throttling ---------- */
function client_ip() {
    /* Trust REMOTE_ADDR only — X-Forwarded-For is user-suppliable on shared hosting. */
    return $_SERVER['REMOTE_ADDR'] ?? '0.0.0.0';
}
function record_attempt($email, $ip, $kind, $ok) {
    try {
        db()->prepare('INSERT INTO auth_attempts (email, ip, kind, ok) VALUES (?,?,?,?)')
            ->execute([strtolower(trim($email)), $ip, $kind, $ok ? 1 : 0]);
    } catch (Exception $e) { /* never let throttling break auth */ }
    /* opportunistic prune — keep last 7 days */
    if (random_int(1, 50) === 1) {
        try {
            db()->prepare("DELETE FROM auth_attempts WHERE ts < datetime('now','-7 days')")->execute();
        } catch (Exception $e) {}
    }
}
function recent_fails($email, $ip, $mins, $email_max, $ip_max) {
    try {
        $pdo = db();
        $st = $pdo->prepare("SELECT COUNT(*) FROM auth_attempts WHERE ok=0 AND ts >= datetime('now', ?) AND email=?");
        $st->execute(['-' . (int)$mins . ' minutes', strtolower(trim($email))]);
        $byEmail = (int)$st->fetchColumn();
        $st = $pdo->prepare("SELECT COUNT(*) FROM auth_attempts WHERE ok=0 AND ts >= datetime('now', ?) AND ip=?");
        $st->execute(['-' . (int)$mins . ' minutes', $ip]);
        $byIp = (int)$st->fetchColumn();
    } catch (Exception $e) {
        return false;
    }
    return $byEmail >= $email_max || $byIp >= $ip_max;
}
function auth_blocked($email, $ip) {
    /* login lockout configurable via App Settings (sec_login_attempts / sec_lockout_minutes) */
    $pdo = db();
    $max = (int)admin_cfg($pdo, 'sec_login_attempts', 10); if ($max < 3) $max = 3; if ($max > 100) $max = 100;
    $mins = (int)admin_cfg($pdo, 'sec_lockout_minutes', 15); if ($mins < 1) $mins = 1; if ($mins > 1440) $mins = 1440;
    return recent_fails($email, $ip, $mins, $max, $max * 4);
}
function otp_blocked($email, $ip) {
    /* OTP: 5 fails/email or 30/IP in 15 min → lock */
    return recent_fails($email, $ip, 15, 5, 30);
}

/* ---------- SMTP (raw socket, STARTTLS, AUTH LOGIN) ---------- */
function smtp_read_reply($sock) {
    $last = '';
    while (($l = fgets($sock, 512)) !== false) {
        $last = trim($l);
        if (strlen($l) > 3 && $l[3] === ' ') break;
    }
    return $last;
}
function smtp_drain_greeting($sock) {
    $last = '';
    while (($l = fgets($sock, 512)) !== false) {
        $last = trim($l);
        if (strlen($l) > 3 && $l[3] === ' ') break;
    }
    return $last;
}
function smtp_send($to, $subject, $html, $text = null) {
    global $SMTP;
    $text = $text ?? strip_tags(str_replace(['<br>', '<br/>', '</p>', '</div>', '</li>'], "\n", $html));
    /* SA1 v21: sanitize every header value at the send boundary (CRLF-injection guard) */
    $to = mail_hdr($to, 320);
    $subject = mail_hdr($subject, 200);
    $fromAddr = mail_hdr($SMTP['from'], 320);
    $host = $SMTP['host']; $port = $SMTP['port'];
    /* non-verifying SSL context so STARTTLS survives self-signed / broken-chain hosts */
    $ctx = stream_context_create(['ssl' => ['verify_peer' => false, 'verify_peer_name' => false]]);
    $sock = @stream_socket_client("tcp://$host:$port", $errno, $errstr, 20, STREAM_CLIENT_CONNECT, $ctx);
    if (!$sock) return false;
    stream_set_timeout($sock, 20);
    smtp_drain_greeting($sock);
    fwrite($sock, "EHLO krtaker.com\r\n");
    smtp_read_reply($sock);
    fwrite($sock, "STARTTLS\r\n");
    $r = smtp_read_reply($sock);
    if (strpos($r, '220') !== false) {
        stream_socket_enable_crypto($sock, true, STREAM_CRYPTO_METHOD_TLS_CLIENT);
        fwrite($sock, "EHLO krtaker.com\r\n");
        smtp_read_reply($sock);
    }
    fwrite($sock, "AUTH LOGIN\r\n"); $r = smtp_read_reply($sock);
    fwrite($sock, base64_encode($SMTP['user']) . "\r\n"); $r = smtp_read_reply($sock);
    fwrite($sock, base64_encode($SMTP['pass']) . "\r\n"); $r = smtp_read_reply($sock);
    if (strpos($r, '235') === false) {
        /* AUTH PLAIN fallback (some servers only accept it, or session desynced after TLS) */
        fwrite($sock, "AUTH PLAIN " . base64_encode("\0{$SMTP['user']}\0{$SMTP['pass']}") . "\r\n"); $r = smtp_read_reply($sock);
        if (strpos($r, '235') === false) { fclose($sock); return false; }
    }
    fwrite($sock, "MAIL FROM:<$fromAddr>\r\n"); smtp_read_reply($sock);
    fwrite($sock, "RCPT TO:<$to>\r\n"); $r = smtp_read_reply($sock);
    if (strpos($r, '250') === false) { fwrite($sock, "QUIT\r\n"); fclose($sock); return false; }
    fwrite($sock, "DATA\r\n"); smtp_read_reply($sock);
    $boundary = 'kr_' . md5(uniqid('', true));
    $fromName = mail_hdr((string)admin_cfg(db(), 'mail_from_name', 'KRTaker'), 60);
    if ($fromName === '') $fromName = 'KRTaker';
    $msg  = "From: $fromName <$fromAddr>\r\n";
    $msg .= "To: <$to>\r\n";
    $msg .= "Subject: $subject\r\n";
    $msg .= "MIME-Version: 1.0\r\n";
    $msg .= "Content-Type: multipart/alternative; boundary=\"$boundary\"\r\n\r\n";
    $msg .= "--$boundary\r\nContent-Type: text/plain; charset=UTF-8\r\n\r\n$text\r\n\r\n";
    $msg .= "--$boundary\r\nContent-Type: text/html; charset=UTF-8\r\n\r\n$html\r\n\r\n";
    $msg .= "--$boundary--\r\n.\r\n";
    fwrite($sock, $msg);
    $r = smtp_read_reply($sock);
    fwrite($sock, "QUIT\r\n");
    fclose($sock);
    return strpos($r, '250') !== false;
}

function esc($s) { return htmlspecialchars((string)$s, ENT_QUOTES, 'UTF-8'); }

/* SA1 v21 hardening: strip CR/LF/NUL from any value that lands in an SMTP header
   (defense in depth against email header injection via user-controlled fields). */
function mail_hdr($s, $max = 200) {
    $s = (string)$s;
    $s = str_replace(["\r", "\n", "\0"], ' ', $s);
    if (strlen($s) > $max) $s = substr($s, 0, $max);
    return $s;
}
/* SA1 v21 hardening: count ALL attempts (successes + failures) for send-throttling
   (recent_fails only counts ok=0, so it can't cap successful sends). */
function recent_any($email, $ip, $mins, $email_max, $ip_max, $kinds = null) {
    try {
        $pdo = db();
        $kindSql = $kinds ? " AND kind IN (" . implode(',', array_fill(0, count($kinds), '?')) . ")" : '';
        $st = $pdo->prepare("SELECT COUNT(*) FROM auth_attempts WHERE ts >= datetime('now', ?) AND email=?" . $kindSql);
        $st->execute(array_merge(['-' . (int)$mins . ' minutes', strtolower(trim($email))], $kinds ?: []));
        $byEmail = (int)$st->fetchColumn();
        $st = $pdo->prepare("SELECT COUNT(*) FROM auth_attempts WHERE ts >= datetime('now', ?) AND ip=?" . $kindSql);
        $st->execute(array_merge(['-' . (int)$mins . ' minutes', $ip], $kinds ?: []));
        $byIp = (int)$st->fetchColumn();
    } catch (Exception $e) {
        return false;
    }
    /* non-positive max = no limit for that dimension */
    return ($email_max > 0 && $byEmail >= $email_max) || ($ip_max > 0 && $byIp >= $ip_max);
}

/* v3.78: seconds until the sliding throttle window clears (oldest failure + window − now).
   $kinds = null → count ALL failures (recent_fails semantics: login/OTP);
   $kinds = [...] → kind-filtered (recent_any semantics: register/resend/forgot/newsletter/contact/payinit). */
function retry_after_secs($email, $ip, $mins, $kinds = null) {
    try {
        $pdo = db();
        $kindSql = $kinds ? " AND kind IN (" . implode(',', array_fill(0, count($kinds), '?')) . ")" : '';
        $args0 = ['-' . (int)$mins . ' minutes'];
        foreach (($kinds ?: []) as $k) $args0[] = (string)$k;
        $best = 0;
        foreach ([['email', strtolower(trim($email))], ['ip', $ip]] as $pair) {
            if ($pair[0] === 'email' && $pair[1] === '') continue;
            $st = $pdo->prepare("SELECT MIN(strftime('%s', ts)) FROM auth_attempts WHERE ok=0 AND ts >= datetime('now', ?) AND " . $pair[0] . "=?" . $kindSql);
            $st->execute(array_merge($args0, [$pair[1]], $kinds ?: []));
            $old = (int)$st->fetchColumn();
            if ($old > 0) $best = max($best, $old + (int)$mins * 60 - time());
        }
        if ($best <= 0) $best = 1;
        return max(1, min((int)$mins * 60, $best));
    } catch (Exception $e) { return (int)$mins * 60; }
}

/* v3.78: emit a 429 with a standards-compliant Retry-After header + JSON retry_after field */
function throttle_out($msg, $email, $ip, $mins, $kinds = null) {
    $ra = retry_after_secs($email, $ip, $mins, $kinds);
    header('Retry-After: ' . $ra);
    json_out(['ok' => false, 'error' => $msg, 'retry_after' => $ra], 429);
}

function mail_fallback($to, $subject, $html, $text = null) {
    $text = $text ?? strip_tags(str_replace(['<br>', '<br/>', '</p>', '</div>', '</li>'], "\n", $html));
    /* SA1 v21: sanitize at the boundary (CRLF-injection guard) */
    $to = mail_hdr($to, 320);
    $subject = mail_hdr($subject, 200);
    $boundary = 'kr_' . md5(uniqid('', true));
    $from = mail_hdr('KRTaker <krtaker@krtaker.com>', 320);
    /* CRITICAL: MIME headers go in the 4th param (additional headers), ONLY the MIME
       parts go in the body. Passing the whole RFC822 message as the body makes the
       MTA deliver it WITHOUT a Content-Type → clients render raw MIME text. */
    $headers = "From: $from\r\nMIME-Version: 1.0\r\nContent-Type: multipart/alternative; boundary=\"$boundary\"";
    $body = "--$boundary\r\nContent-Type: text/plain; charset=UTF-8\r\n\r\n$text\r\n\r\n"
          . "--$boundary\r\nContent-Type: text/html; charset=UTF-8\r\n\r\n$html\r\n\r\n"
          . "--$boundary--";
    /* v3.85: pass -f so the ENVELOPE sender is krtaker@krtaker.com (defaults to
       krtaker@server.coderdrop.com otherwise) — SPF+DKIM double alignment for
       Gmail/Outlook. Verified 2026-08-09 via live probe: Return-Path was
       server.coderdrop.com before, krtaker@krtaker.com after. */
    return @mail($to, $subject, $body, $headers, '-fkrtaker@krtaker.com');
}

function send_mail($to, $subject, $html, $text = null, $queued = false) {
    if ($queued) return queue_mail($to, $subject, $html, $text);
    if (smtp_send($to, $subject, $html, $text)) return true;
    return mail_fallback($to, $subject, $html, $text);
}

/* ── Mail queue (off-request-path sending, 2026-08-09) ──
   Heavy/aggregate mail (collections digest, rent reminders, welcome sequence)
   is enqueued and drained by the app-mail-worker endpoint (service-key gated,
   called by a cron). OTP/verify emails stay INLINE (time-sensitive, 5-min code
   expiry). Create the table idempotently so it exists on both fresh and old DBs. */
function mail_queue_table($pdo) {
    $pdo->exec("CREATE TABLE IF NOT EXISTS mail_queue (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        to_addr TEXT, subject TEXT, html TEXT, text_body TEXT,
        status TEXT DEFAULT 'pending', attempts INTEGER DEFAULT 0,
        last_error TEXT DEFAULT '', created_at TEXT DEFAULT (datetime('now')),
        sent_at TEXT)");
}

function queue_mail($to, $subject, $html, $text = null) {
    try {
        $pdo = db();
        mail_queue_table($pdo);
        $st = $pdo->prepare('INSERT INTO mail_queue (to_addr, subject, html, text_body) VALUES (?,?,?,?)');
        return $st->execute([$to, $subject, $html, $text]);
    } catch (Exception $e) {
        /* queue is best-effort — if it fails, fall back to inline so mail is not lost */
        return smtp_send($to, $subject, $html, $text) || mail_fallback($to, $subject, $html, $text);
    }
}

/* Drain up to $limit pending queue rows; returns ['sent'=>n,'failed'=>n,'left'=>n].
   Called by the app-mail-worker endpoint. Max 3 attempts per row, then marked dead. */
function mail_queue_drain($pdo, $limit = 50) {
    mail_queue_table($pdo);
    $sent = 0; $failed = 0;
    $rows = $pdo->prepare('SELECT * FROM mail_queue WHERE status=? ORDER BY id LIMIT ' . (int)$limit);
    $rows->execute(['pending']);
    foreach ($rows->fetchAll(PDO::FETCH_ASSOC) as $r) {
        $ok = smtp_send($r['to_addr'], $r['subject'], $r['html'], $r['text_body'])
            || mail_fallback($r['to_addr'], $r['subject'], $r['html'], $r['text_body']);
        if ($ok) {
            $pdo->prepare("UPDATE mail_queue SET status='sent', sent_at=datetime('now') WHERE id=?")->execute([$r['id']]);
            $sent++;
        } else {
            $att = (int)$r['attempts'] + 1;
            $st = $att >= 3 ? 'dead' : 'pending';
            $pdo->prepare("UPDATE mail_queue SET attempts=?, status=?, last_error=? WHERE id=?")
                ->execute([$att, $st, 'send failed x' . $att, $r['id']]);
            $failed++;
        }
    }
    $left = (int)$pdo->query("SELECT COUNT(*) FROM mail_queue WHERE status='pending'")->fetchColumn();
    return ['sent' => $sent, 'failed' => $failed, 'left' => $left];
}

/* ── SA1 v19: Web Push (RFC 8291 content-encryption + RFC 8292 VAPID) — keys from env file ── */
define('VAPID_PRIV', krenv('VAPID_PRIV', PUSH_VAPID_PRIV));
define('VAPID_PUB', krenv('VAPID_PUB', PUSH_VAPID_PUB));
define('VAPID_SUB', krenv('VAPID_SUB', 'mailto:owner@krtaker.com'));

function b64url_encode($s) { return rtrim(strtr(base64_encode($s), '+/', '-_'), '='); }
function b64url_decode($s) { return base64_decode(strtr($s, '-_', '+/')); }

/* Build an EC public-key PEM from a raw 65-byte uncompressed point (openssl needs PEM, not raw DER) */
function ec_spki($raw) {
    $der = hex2bin('3059301306072a8648ce3d020106082a8648ce3d030107034200') . $raw;
    return "-----BEGIN PUBLIC KEY-----\n" . chunk_split(base64_encode($der), 64, "\n") . "-----END PUBLIC KEY-----\n";
}

function vapid_public_b64url() {
    $d = openssl_pkey_get_details(openssl_pkey_get_public(VAPID_PUB));
    return b64url_encode("\x04" . $d['ec']['x'] . $d['ec']['y']);
}

function vapid_jwt($aud) {
    $h = b64url_encode(json_encode(['typ' => 'JWT', 'alg' => 'ES256']));
    $c = b64url_encode(json_encode(['aud' => $aud, 'exp' => time() + 12 * 3600, 'sub' => VAPID_SUB]));
    $input = $h . '.' . $c;
    openssl_sign($input, $sig, VAPID_PRIV, OPENSSL_ALGO_SHA256);
    /* DER-encoded ECDSA signature → raw r||s (64 bytes) */
    $i = 2; $r = $s = '';
    if (isset($sig[2]) && $sig[2] === "\x02") { $l = ord($sig[3]); $r = substr($sig, 4, $l); $i = 4 + $l; }
    if (isset($sig[$i]) && $sig[$i] === "\x02") { $l = ord($sig[$i + 1]); $s = substr($sig, $i + 2, $l); }
    if (strlen($r) === 33 && $r[0] === "\x00") $r = substr($r, 1);
    if (strlen($s) === 33 && $s[0] === "\x00") $s = substr($s, 1);
    $raw = str_pad($r, 32, "\x00", STR_PAD_LEFT) . str_pad($s, 32, "\x00", STR_PAD_LEFT);
    return $input . '.' . b64url_encode($raw);
}

/* RFC 5869 HKDF-Expand (no re-extract — hash_hkdf() re-extracts and is NOT RFC 8291 compatible) */
function hkdf_expand($prk, $info, $len) {
    $out = ''; $t = ''; $i = 1;
    while (strlen($out) < $len) {
        $t = hash_hmac('sha256', $t . $info . chr($i), $prk, true);
        $out .= $t; $i++;
    }
    return substr($out, 0, $len);
}

/* Encrypt a JSON payload for a PushSubscription (RFC 8291 aes128gcm) */
function webpush_encrypt($p256dh, $auth, $payload) {
    $ua_pub = b64url_decode($p256dh);
    $ua_auth = b64url_decode($auth);
    /* openssl_pkey_derive() only accepts a PEM string — convert the raw point via SPKI → PEM */
    $ua_pem = openssl_pkey_get_details(openssl_pkey_get_public(ec_spki($ua_pub)))['key'];
    $srv_res = openssl_pkey_get_private(VAPID_PRIV);
    $sd = openssl_pkey_get_details(openssl_pkey_get_public(VAPID_PUB));
    $server_pub = "\x04" . $sd['ec']['x'] . $sd['ec']['y'];
    $salt = random_bytes(16);
    $shared = openssl_pkey_derive($ua_pem, $srv_res);
    $key_info = 'Web Push: info' . $ua_pub . $server_pub;
    $prk = hash_hmac('sha256', $shared, $salt, true);
    $ikm = hkdf_expand($prk, $key_info, 32);
    $prk2 = hash_hmac('sha256', $ikm, $ua_auth, true);
    $cek = hkdf_expand($prk2, "Content-Encoding: aes128gcm\0", 16);
    $nonce = hkdf_expand($prk2, "Content-Encoding: nonce\0", 12);
    $header = $salt . pack('N', 4096) . chr(65) . $server_pub;
    $tag = '';
    $cipher = openssl_encrypt("\x02" . $payload, 'aes-128-gcm', $cek, OPENSSL_RAW_DATA, $nonce, $tag, $header);
    return $header . $cipher . $tag;
}

/* POST the encrypted payload to the push service; returns HTTP result */
function webpush_send($endpoint, $p256dh, $auth, $payload, $ttl = 86400) {
    $body = webpush_encrypt($p256dh, $auth, $payload);
    $u = parse_url($endpoint);
    $origin = $u['scheme'] . '://' . $u['host'];
    $jwt = vapid_jwt($origin);
    $headers = [
        'Content-Type: application/octet-stream',
        'Content-Encoding: aes128gcm',
        'TTL: ' . $ttl,
        'Urgency: normal',
        'Authorization: vapid t=' . $jwt . ', k=' . vapid_public_b64url(),
        'Content-Length: ' . strlen($body),
    ];
    $ch = curl_init($endpoint);
    curl_setopt_array($ch, [
        CURLOPT_POST => true,
        CURLOPT_POSTFIELDS => $body,
        CURLOPT_HTTPHEADER => $headers,
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_TIMEOUT => 20,
        CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_2_0,
        CURLOPT_SSL_VERIFYPEER => true,
    ]);
    $resp = curl_exec($ch);
    $code = (int)curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
    $err = curl_error($ch);
    curl_close($ch);
    return ['code' => $code, 'err' => $err, 'resp' => substr((string)$resp, 0, 200)];
}

/* Send a notification to every device registered for an email */
function push_to_user($pdo, $email, $title, $body, $url = '/app-v3/') {
    if (!$email) return ['sent' => 0, 'removed' => 0, 'errors' => []];
    $st = $pdo->prepare('SELECT endpoint, p256dh, auth FROM push_subs WHERE sub_email=?');
    $st->execute([$email]);
    $rows = $st->fetchAll(PDO::FETCH_ASSOC);
    if (!$rows) return ['sent' => 0, 'removed' => 0, 'errors' => []];
    $payload = json_encode(['title' => $title, 'body' => $body, 'url' => $url], JSON_UNESCAPED_UNICODE);
    $sent = 0; $removed = 0; $errors = [];
    foreach ($rows as $r) {
        $res = webpush_send($r['endpoint'], $r['p256dh'], $r['auth'], $payload);
        if ($res['code'] === 201) { $sent++; }
        elseif ($res['code'] === 404 || $res['code'] === 410) {
            try { $pdo->prepare('DELETE FROM push_subs WHERE endpoint=?')->execute([$r['endpoint']]); $removed++; } catch (Exception $e) {}
        } else { $errors[] = ['code' => $res['code'], 'err' => $res['err']]; }
    }
    return ['sent' => $sent, 'removed' => $removed, 'errors' => $errors];
}

/* Push all active owners (V2.14 — trigger helper; never breaks the primary action).
   $actor = acting user row — owner/superadmin-initiated actions are skipped. */
function push_owners($pdo, $title, $body, $url = '/app-v3/', $actor = null, $atype = 'system', $aref = '') {
    try {
        if ($actor && in_array($actor['role'] ?? '', ['superadmin', 'owner'], true)) return;
        $rows = $pdo->query("SELECT id, email FROM subscribers WHERE status='active' ORDER BY id")->fetchAll(PDO::FETCH_ASSOC);
        if (!$rows) $rows = [];
        $sev = $atype === 'payment' ? 'success' : ($atype === 'maintenance' || $atype === 'kyc' ? 'warning' : 'info');
        foreach ($rows as $row) {
            if (!empty($row['email'])) push_to_user($pdo, $row['email'], $title, $body, $url);
            if (!empty($row['id'])) kr_alert_upsert($pdo, 'sub:' . $row['id'], $atype, $sev, $title, $body, $aref);
        }
    } catch (Throwable $e) { /* push must never break the primary action */ }
}

/* ── SA1 v20: subscriber team (sub-accounts) + seat enforcement ── */
function team_owner_only($u) {
    if ($u['role'] === 'superadmin') return true;
    if (($u['kind'] ?? '') !== 'sub' || $u['role'] !== 'owner' || !empty($u['team_member']))
        return false;
    return true;
}
function team_scope_email($u, $body, $pdo) {
    /* owner → own email; superadmin → optional target email */
    if ($u['role'] === 'superadmin') {
        $em = strtolower(trim($body['email'] ?? ''));
        if (!$em) {
            $first = $pdo->query("SELECT email FROM subscribers WHERE status='active' ORDER BY id LIMIT 1")->fetchColumn();
            return $first ?: '';
        }
        return $em;
    }
    return $u['email'];
}
function team_revoke_tokens($pdo, $team_id) {
    $pdo->prepare("DELETE FROM app_tokens WHERE kind='team' AND user_id=?")->execute([$team_id]);
}

