function next_id($table, $prefix, $pad) {
    $mx = db()->query("SELECT MAX(CAST(REPLACE(id,'" . $prefix . "','') AS INTEGER)) FROM " . $table)->fetchColumn();
    return $prefix . str_pad((string)((int)$mx + 1), $pad, '0', STR_PAD_LEFT);
}
/* ── SA1 v25.6: row-ownership resolver for app-crud — maps any CRUD-able row to its owning
   subscriber email. properties/units/tenants/partners carry sub_email directly; the rest
   resolve through the parent chain (lease→unit→prop, invoice→lease→unit→prop,
   ticket→unit→prop, amenity→unit→prop). Returns '' when the row cannot be attributed
   (shared/global rows) and false when the row does not exist. ── */
function crud_row_owner($pdo, $collection, $id) {
    $tables = ['properties','units','shops','tenants','partners','leases','invoices','tickets','amenities'];
    if (!in_array($collection, $tables, true)) return '';   // not an ownership-scoped table
    try {
        if (in_array($collection, ['properties','units','shops','tenants','partners'], true)) {
            $st = $pdo->prepare("SELECT sub_email FROM $collection WHERE id=?");
            $st->execute([$id]);
            $v = $st->fetchColumn();
            if ($v === false) return false;
            return (string)$v;
        }
        if ($collection === 'leases') {
            $st = $pdo->prepare("SELECT u.sub_email FROM leases l JOIN units u ON u.id=l.u WHERE l.id=?");
            $st->execute([$id]);
            $v = $st->fetchColumn();
            if ($v === false) return false;
            return (string)$v;
        }
        if ($collection === 'invoices') {
            $st = $pdo->prepare("SELECT u.sub_email FROM invoices i JOIN leases l ON l.id=i.l JOIN units u ON u.id=l.u WHERE i.id=?");
            $st->execute([$id]);
            $v = $st->fetchColumn();
            if ($v === false) return false;
            return (string)$v;
        }
        if ($collection === 'tickets') {
            $st = $pdo->prepare("SELECT u.sub_email FROM tickets t JOIN units u ON u.id=t.u WHERE t.id=?");
            $st->execute([$id]);
            $v = $st->fetchColumn();
            if ($v === false) return false;
            return (string)$v;
        }
        if ($collection === 'amenities') {
            /* building-level amenities carry unit='' → resolve owner via prop fallback */
            $st = $pdo->prepare("SELECT a.id, COALESCE(u.sub_email, p.sub_email) FROM amenities a LEFT JOIN units u ON u.id=a.unit LEFT JOIN properties p ON p.id=a.prop WHERE a.id=?");
            $st->execute([$id]);
            $row = $st->fetch(PDO::FETCH_NUM);
            if ($row === false) return false;   // amenity row missing → 404
            return (string)$row[1];             // '' = shared/unattributable → allowed
        }
    } catch (Exception $e) { return ''; }
    return '';
}
/* subscriber row-scope guard for update/delete — blocks cross-account writes on app-crud */
function crud_guard_owner($pdo, $u, $collection, $id) {
    if (($u['kind'] ?? '') !== 'sub') return;               // staff/team overlay inherit parent scope
    /* partner tickets are scoped by the dedicated `con` (assigned company) check in app-crud —
       the unit→property chain resolves to the building owner's email and would 403 legit jobs */
    if (($u['role'] ?? '') === 'partner' && $collection === 'tickets') return;
    $own = crud_row_owner($pdo, $collection, $id);
    if ($own === false) json_out(['ok' => false, 'error' => 'Record not found.'], 404);
    if ($own !== '' && strtolower(trim($own)) !== strtolower(trim($u['email'])))
        json_out(['ok' => false, 'error' => 'This record belongs to another account.'], 403);
}
/* tenant/partner own-scope helpers */
function my_units($u) {
    $pdo = db();
    $tid = tenant_resolve_id($pdo, $u['email']);
    if (!$tid) return [];
    $st = $pdo->prepare('SELECT u FROM leases WHERE t=?');
    $st->execute([$tid]);
    return $st->fetchAll(PDO::FETCH_COLUMN);
}
function my_org($u) {
    $pdo = db();
    $st = $pdo->prepare('SELECT name FROM partners WHERE sub_email=?');
    $st->execute([$u['email']]);
    $n = $st->fetchColumn();
    return $n ?: $u['org'] ?? '';
}

/* ---------- Phase 4: payment gateways (bKash / SSLCommerz / Nagad) ----------
   Sandbox mode: init returns a simulated checkout; confirm records the payment.
   Go live: paste real merchant credentials below and set sandbox=false. */
function GATEWAYS() {
    $gw = [
        'bkash' => [
            'name' => 'bKash', 'sandbox' => true,
            'merchant' => '013000000000',          // ← live App Key / wallet no.
            'app_secret' => 'REPLACE_ME',          // ← live bKash tokenized-checkout App Secret
            'checkout' => 'https://tokenized.sandbox.bka.sh/v1.2.0-beta/tokenized/checkout/create',
        ],
        'sslcommerz' => [
            'name' => 'SSLCommerz', 'sandbox' => true,
            'store_id' => 'krtakerTEST',           // ← live Store ID
            'store_pass' => 'REPLACE_ME',          // ← live Store Password
            'checkout' => 'https://sandbox.sslcommerz.com/gwprocess/v4/api.php',
            'kyc' => true,                         // V2.10.0: card payments require verified tenant KYC
        ],
        'nagad' => [
            'name' => 'Nagad', 'sandbox' => true,
            'merchant' => 'NAGAD_MERCHANT_ID',     // ← live merchant id
            'checkout' => 'https://sandbox.mynagad.com/api/dfs/check-out/initialize',
        ],
    ];
    /* SA1: super-admin payment-integration overrides (platform_meta gw_config JSON) */
    try {
        $ov = json_decode((string)db()->query("SELECT v FROM platform_meta WHERE k='gw_config'")->fetchColumn(), true);
        if (is_array($ov)) foreach ($ov as $code => $cfg) {
            if (!isset($gw[$code]) || !is_array($cfg)) continue;
            foreach ($cfg as $k => $v) {
                if ($k === 'sandbox') { $gw[$code]['sandbox'] = !empty($v); }
                elseif (array_key_exists($k, $gw[$code])) { $gw[$code][$k] = (string)$v; }
            }
        }
    } catch (Exception $e) { /* schema not ready yet — keep defaults */ }
    return $gw;
}
function gateway_label($code) {
    $g = GATEWAYS()[$code] ?? null;
    return $g ? $g['name'] : $code;
}
/* Real sandbox/live gateway adapters. Credentials live in GATEWAYS(); while any
   credential is the placeholder, the flow falls back to the simulated checkout
   (pure demo). Set the credentials (and sandbox=false to go live) and these
   adapters take over with ZERO code changes. */
function gateway_ready($code) {
    $g = GATEWAYS()[$code] ?? null;
    if (!$g) return false;
    if ($code === 'sslcommerz') return !in_array($g['store_id'], ['', 'REPLACE_ME', 'krtakerTEST'], true) && $g['store_pass'] !== 'REPLACE_ME';
    if ($code === 'bkash') return $g['merchant'] !== '013000000000' && $g['app_secret'] !== 'REPLACE_ME';
    if ($code === 'nagad') return $g['merchant'] !== 'NAGAD_MERCHANT_ID';
    return false;
}
function gw_http_post($url, $fields) {
    $ch = curl_init($url);
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true, CURLOPT_POST => true, CURLOPT_TIMEOUT => 40,
        CURLOPT_POSTFIELDS => is_array($fields) ? http_build_query($fields) : $fields,
        CURLOPT_HTTPHEADER => ['Content-Type: application/x-www-form-urlencoded'],
    ]);
    $body = curl_exec($ch); $err = curl_error($ch); $code = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
    if ($err) return ['error' => $err];
    return ['code' => $code, 'body' => $body];
}
function gateway_init($code, $tx, $inv, $due, $u) {
    $g = GATEWAYS()[$code];
    $cb = 'https://krtaker.com/app-v3/#/dashboard?gw=' . $code . '&sid=' . urlencode($tx['id']);
    if ($code === 'sslcommerz') {
        $r = gw_http_post($g['checkout'], [
            'store_id' => $g['store_id'], 'store_passwd' => $g['store_pass'],
            'total_amount' => $due, 'currency' => 'BDT', 'tran_id' => $tx['id'],
            'success_url' => $cb, 'fail_url' => $cb, 'cancel_url' => $cb,
            'cus_name' => $u['name'], 'cus_email' => $u['email'],
            'cus_phone' => $u['phone'] ?? '01700000000',
            'product_category' => 'Rent', 'product_name' => 'Rent ' . $inv,
            'num_of_item' => 1, 'quantity' => 1, 'weight' => 0, 'shipping_method' => 'NO',
        ]);
        if (isset($r['error'])) return ['error' => 'SSLCommerz unreachable: ' . $r['error']];
        $j = json_decode($r['body'], true);
        if (!$j || ($j['status'] ?? '') !== 'SUCCESS') return ['error' => 'SSLCommerz: ' . ($j['failedreason'] ?? 'init failed')];
        return ['ok' => true, 'url' => $j['GatewayPageURL'] ?: $j['redirectGatewayURL'], 'gw_ref' => $tx['id']];
    }
    if ($code === 'bkash') {
        /* tokenized checkout: grant token → create payment */
        $tokUrl = str_replace('/checkout/create', '/checkout/token/grant', $g['checkout']);
        $r = gw_http_post($tokUrl, ['app_key' => $g['merchant'], 'app_secret' => $g['app_secret']]);
        if (isset($r['error'])) return ['error' => 'bKash unreachable: ' . $r['error']];
        $tok = json_decode($r['body'], true);
        if (empty($tok['id_token'])) return ['error' => 'bKash token grant failed: ' . substr($r['body'], 0, 200)];
        $ch = curl_init($g['checkout']);
        curl_setopt_array($ch, [
            CURLOPT_RETURNTRANSFER => true, CURLOPT_POST => true, CURLOPT_TIMEOUT => 40,
            CURLOPT_HTTPHEADER => ['Content-Type: application/json', 'Authorization: ' . $tok['id_token'], 'X-APP-Key: ' . $g['merchant']],
            CURLOPT_POSTFIELDS => json_encode([
                'mode' => '0011', 'callbackURL' => $cb, 'payerReference' => $inv,
                'amount' => (string)$due, 'currency' => 'BDT', 'merchantInvoiceNumber' => $tx['id'],
            ]),
        ]);
        $body = curl_exec($ch); curl_close($ch);
        $j = json_decode((string)$body, true);
        if (empty($j['bkashURL'])) return ['error' => 'bKash create failed: ' . substr((string)$body, 0, 200)];
        return ['ok' => true, 'url' => $j['bkashURL'], 'gw_ref' => $j['paymentID'] ?? $tx['id']];
    }
    if ($code === 'nagad') {
        /* Nagad DFS: initialize → get an order id + URL */
        $r = gw_http_post($g['checkout'] . '/' . $g['merchant'] . '/' . $tx['id'], [
            'accountNumber' => $g['merchant'], 'amount' => (string)$due, 'currency' => '050',
            'merchantCallbackURL' => $cb, 'orderId' => $tx['id'], 'ip' => '127.0.0.1',
        ]);
        if (isset($r['error'])) return ['error' => 'Nagad unreachable: ' . $r['error']];
        $j = json_decode($r['body'], true);
        if (empty($j['callBackUrl'])) return ['error' => 'Nagad init failed: ' . substr($r['body'], 0, 200)];
        return ['ok' => true, 'url' => $j['callBackUrl'], 'gw_ref' => $j['orderId'] ?? $tx['id']];
    }
    return ['error' => 'Unsupported gateway.'];
}
function gateway_verify($code, $gw_ref) {
    /* Returns true when the gateway confirms the payment succeeded. */
    $g = GATEWAYS()[$code];
    if ($code === 'sslcommerz') {
        /* Live validator when gw_config flips sandbox=false; sandbox otherwise. */
        $val = !empty($g['sandbox'])
            ? 'https://sandbox.sslcommerz.com/validator/api/validationserverAPI.php'
            : 'https://validator.sslcommerz.com/validationserverAPI.php';
        $r = gw_http_post($val, [
            'val_id' => $gw_ref, 'store_id' => $g['store_id'], 'store_passwd' => $g['store_pass'], 'format' => 'json',
        ]);
        $j = json_decode($r['body'] ?? '', true);
        /* v4 IPN hardening: status VALID + currency BDT + amount > 0. The exact
           amount-vs-session check happens in gateway_confirm_session where the
           expected amount is known (the validator echoes amount — the handler
           compares it to the local session's amount). */
        return ($j['status'] ?? '') === 'VALID'
            && ($j['currency'] ?? '') === 'BDT'
            && (int)($j['amount'] ?? 0) > 0;
    }
    if ($code === 'bkash') {
        $r = gw_http_post($g['checkout'] . '/execute', ['paymentID' => $gw_ref]);
        $j = json_decode($r['body'] ?? '', true);
        return ($j['transactionStatus'] ?? '') === 'Completed';
    }
    if ($code === 'nagad') {
        $r = gw_http_post($g['checkout'] . '/complete/' . $g['merchant'] . '/' . $gw_ref, []);
        $j = json_decode($r['body'] ?? '', true);
        return ($j['status'] ?? '') === 'Success';
    }
    return false;
}

/* ── Gateway session confirmation (idempotent, IPN + redirect share this) ──
   Atomic status flip: only a tx in pending/redirecting may become 'paid'. If the
   flip affects 0 rows the session was already confirmed → no double payment. */
function gateway_confirm_session($pdo, $sid, $gref, $actor) {
    $st = $pdo->prepare('SELECT * FROM gateway_tx WHERE id=?'); $st->execute([$sid]);
    $tx = $st->fetch(PDO::FETCH_ASSOC);
    if (!$tx) return ['ok' => false, 'error' => 'Checkout session not found.', 'code' => 404];
    if ($tx['status'] === 'paid') {
        /* idempotent replay: return the already-recorded payment info */
        $pay = $pdo->prepare("SELECT * FROM payments WHERE inv=? AND ref=? ORDER BY id DESC LIMIT 1");
        $pay->execute([$tx['invoice_id'], $tx['ref']]);
        $p = $pay->fetch(PDO::FETCH_ASSOC);
        return ['ok' => true, 'idempotent' => true, 'payment' => $p['id'] ?? '', 'receipt' => ''];
    }
    if ($tx['status'] !== 'pending' && $tx['status'] !== 'redirecting') {
        return ['ok' => false, 'error' => 'Session already ' . $tx['status'] . '.', 'code' => 400];
    }
    /* verify with the gateway BEFORE recording (only when a real ref exists) */
    if (!empty($tx['gw_ref'])) {
        $code = strtolower(array_search($tx['method'], array_map(fn($g) => $g['name'], GATEWAYS()), true) ?: '');
        $ok = false;
        if ($gref) $ok = gateway_verify($code, $gref);
        if (!$ok) {
            audit($actor, 'Gateway verification failed', 'payments', $sid, $code . ' ' . $gref);
            return ['ok' => false, 'error' => 'Gateway could not verify this payment (' . $code . '). If you paid, contact support with session ' . $sid . '.', 'code' => 402];
        }
        /* amount check: validator echoes the gateway-recorded amount — it must
           match our session amount (prevents underpayment/overpayment replay) */
        $g = GATEWAYS()[$code];
        if ($code === 'sslcommerz') {
            $val = !empty($g['sandbox'])
                ? 'https://sandbox.sslcommerz.com/validator/api/validationserverAPI.php'
                : 'https://validator.sslcommerz.com/validationserverAPI.php';
            $vr = gw_http_post($val, ['val_id' => $gref, 'store_id' => $g['store_id'], 'store_passwd' => $g['store_pass'], 'format' => 'json']);
            $vj = json_decode($vr['body'] ?? '', true);
            $gwAmt = (int)($vj['amount'] ?? 0);
            if ($gwAmt > 0 && $gwAmt !== (int)$tx['amount']) {
                audit($actor, 'Gateway amount mismatch', 'payments', $sid, 'session=' . $tx['amount'] . ' gw=' . $gwAmt);
                return ['ok' => false, 'error' => 'Amount mismatch with gateway. Contact support with session ' . $sid . '.', 'code' => 402];
            }
        }
    }
    /* atomic flip — the idempotency barrier */
    $up = $pdo->prepare("UPDATE gateway_tx SET status='paid', updated_at=datetime('now'), gw_ref=COALESCE(NULLIF(?,''),gw_ref) WHERE id=? AND status IN ('pending','redirecting')");
    $up->execute([$gref, $sid]);
    if ($up->rowCount() === 0) {
        /* lost the race → already paid by a concurrent request */
        $pay = $pdo->prepare("SELECT * FROM payments WHERE inv=? AND ref=? ORDER BY id DESC LIMIT 1");
        $pay->execute([$tx['invoice_id'], $tx['ref']]);
        $p = $pay->fetch(PDO::FETCH_ASSOC);
        return ['ok' => true, 'idempotent' => true, 'payment' => $p['id'] ?? '', 'receipt' => ''];
    }
    try {
        list($pid, $rid) = record_payment($pdo, $tx['invoice_id'], (int)$tx['amount'], $tx['method'], $tx['ref'], gmdate('Y-m-d'));
    } catch (Exception $e) {
        return ['ok' => false, 'error' => 'Payment failed: ' . $e->getMessage(), 'code' => 500];
    }
    audit($actor, 'Gateway payment confirmed', 'payments', $pid, $tx['invoice_id'] . ' ' . $tx['amount'] . ' via ' . $tx['method']);
    return ['ok' => true, 'payment' => $pid, 'receipt' => $rid, 'gateway' => $tx['method']];
}

/* ── Payment-failed notification (V2.40): email the payer + push the owner when a
   gateway session fails or is cancelled. Mirrors the receipt/push semantics —
   invoice stays unpaid, no money deducted, retry link included. ── */
function notify_payment_failed($pdo, $sid, $reason) {
    try {
        $st = $pdo->prepare('SELECT * FROM gateway_tx WHERE id=?'); $st->execute([$sid]);
        $tx = $st->fetch(PDO::FETCH_ASSOC);
        if (!$tx) return;
        $amt = (int)$tx['amount'];
        $pay_url = 'https://krtaker.com/app-v3/#/invoices?open=' . rawurlencode($tx['invoice_id']) . '&pay=1';
        /* who pays? tenant on the invoice's lease (portal payer), else the invoice owner */
        $payer = '';
        $st = $pdo->prepare('SELECT t.email, t.name FROM invoices i LEFT JOIN leases l ON l.id=i.l LEFT JOIN tenants t ON t.id=l.t WHERE i.id=?');
        $st->execute([$tx['invoice_id']]); $pt = $st->fetch(PDO::FETCH_ASSOC);
        if ($pt) { $payer = $pt['email']; $pname = $pt['name'] ?: 'there'; }
        else { $payer = ''; $pname = 'there'; }
        if ($payer === '') {
            $st = $pdo->prepare('SELECT COALESCE(u.sub_email, p.sub_email, \'\') FROM invoices i LEFT JOIN leases l ON l.id=i.l LEFT JOIN units u ON u.id=l.u LEFT JOIN properties p ON p.id=u.p WHERE i.id=?');
            $st->execute([$tx['invoice_id']]); $payer = (string)$st->fetchColumn(); $pname = 'there';
        }
        if ($payer !== '' && mail_switch($pdo, 'docs')) {
            list($s, $h) = email_render('payment_failed', [
                'name' => $pname, 'amount' => number_format($amt), 'invoice_id' => $tx['invoice_id'],
                'method' => $tx['method'], 'reason' => $reason, 'pay_url' => $pay_url,
            ]);
            send_mail($payer, $s, $h, null, true);   /* queued — respects the mail worker */
            audit('system', 'Payment-failed email queued', 'payments', $sid, $tx['invoice_id'] . ' ' . $amt . ' ' . $tx['method']);
        }
        /* push the property owner so they can follow up (payer != owner) */
        $st = $pdo->prepare('SELECT COALESCE(u.sub_email, p.sub_email, \'\') FROM invoices i LEFT JOIN leases l ON l.id=i.l LEFT JOIN units u ON u.id=l.u LEFT JOIN properties p ON p.id=u.p WHERE i.id=?');
        $st->execute([$tx['invoice_id']]); $own = (string)$st->fetchColumn();
        if ($own !== '' && strcasecmp($own, $payer) !== 0)
            push_to_user($pdo, $own, '⚠️ Payment failed — ' . $tx['invoice_id'],
                'A payment of ৳' . number_format($amt) . ' via ' . $tx['method'] . ' was not completed (' . $reason . ').',
                '/app-v3/#/invoices?open=' . rawurlencode($tx['invoice_id']));
    } catch (Exception $e) {}
}

function invoice_owner_check($u, $inv) {
    /* tenant may only pay invoices on their own leases; staff may pay any */
    if ($u['role'] !== 'tenant') return true;
    $pdo = db();
    $tid = tenant_resolve_id($pdo, $u['email']);
    if (!$tid) return false;
    $st = $pdo->prepare('SELECT COUNT(*) FROM leases WHERE t=? AND id IN (SELECT l FROM invoices WHERE id=?)');
    $st->execute([$tid, $inv]);
    return (int)$st->fetchColumn() > 0;
}
function invoice_due($pdo, $inv) {
    $st = $pdo->prepare('SELECT * FROM invoices WHERE id=?'); $st->execute([$inv]);
    $row = $st->fetch(PDO::FETCH_ASSOC);
    if (!$row) return null;
    $st = $pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM payments WHERE inv=?'); $st->execute([$inv]);
    $paid = (int)$st->fetchColumn();
    $due = (int)$row['net'] - $paid;
    return ['row' => $row, 'paid' => $paid, 'due' => $due];
}
/* Atomic payment + signed receipt + invoice ripple (shared by manual & gateway paths) */
function record_payment($pdo, $inv, $amount, $method, $ref, $date) {
    $mx = (int)$pdo->query("SELECT MAX(CAST(REPLACE(id,'PAY-','') AS INTEGER)) FROM payments")->fetchColumn();
    $pid = 'PAY-' . str_pad((string)($mx + 1), 3, '0', STR_PAD_LEFT);
    $rx = (int)$pdo->query("SELECT MAX(CAST(REPLACE(id,'RCP-','') AS INTEGER)) FROM receipts")->fetchColumn();
    $rid = 'RCP-' . str_pad((string)($rx + 1), 4, '0', STR_PAD_LEFT);
    $pdo->beginTransaction();
    try {
        $pdo->prepare('INSERT INTO payments (id, inv, amount, method, ref, date, status) VALUES (?,?,?,?,?,?,?)')
            ->execute([$pid, $inv, $amount, $method, $ref, $date, 'Success']);
        $pdo->prepare('INSERT INTO receipts (id, inv, amount, date, method, sig) VALUES (?,?,?,?,?,?)')
            ->execute([$rid, $inv, $amount, $date, $method, 'SIG-' . bin2hex(random_bytes(4))]);
        /* ripple: mark invoice Paid when balance is cleared */
        $due = invoice_due($pdo, $inv);
        if ($due && $due['due'] <= 0) {
            $pdo->prepare('UPDATE invoices SET status="Paid" WHERE id=?')->execute([$inv]);
        }
        $pdo->commit();
    } catch (Exception $e) {
        $pdo->rollBack();
        throw $e;
    }
    return [$pid, $rid];
}

/* ═══════════════════════════ PHASE 5 — KR AI (DeepSeek + offline fallback) ═══════════════════════════ */
function AI_CONFIG($pdo = null) {
    /* Key resolution order: env KRT_DS_KEY → admin_settings ai_key → REPLACE_ME (offline).
       Provider/model/base_url come from App Settings (ai_provider/ai_model) and the AI
       caretaker console (ai_key/ai_base_url). provider=offline always forces offline mode. */
    $key = getenv('KRT_DS_KEY') ?: '';
    $provider = 'deepseek'; $model = 'deepseek-chat';
    $url = 'https://api.deepseek.com/chat/completions';
    if ($pdo) {
        $provider = admin_cfg($pdo, 'ai_provider', 'deepseek');
        $model = admin_cfg($pdo, 'ai_model', 'deepseek-chat');
        if ($key === '') { $k2 = admin_cfg($pdo, 'ai_key', ''); if ($k2 !== '' && $k2 !== 'REPLACE_ME') $key = $k2; }
        $bu = trim(admin_cfg($pdo, 'ai_base_url', ''));
        if ($provider === 'openai')        $url = $bu !== '' ? $bu : 'https://api.openai.com/v1/chat/completions';
        elseif ($provider === 'deepseek')  $url = $bu !== '' ? $bu : 'https://api.deepseek.com/chat/completions';
        elseif ($provider === 'offline')   $key = 'REPLACE_ME';
        else { $provider = 'deepseek'; $model = 'deepseek-chat'; $url = 'https://api.deepseek.com/chat/completions'; }
    } elseif ($key === '') { $key = 'REPLACE_ME'; }
    return ['key' => $key ?: 'REPLACE_ME', 'model' => $model, 'url' => $url, 'provider' => $provider];
}
function ai_mode($pdo = null) { return AI_CONFIG($pdo)['key'] !== 'REPLACE_ME' ? 'llm' : 'offline'; }

/* Curated Bangladeshi property-law knowledge base (PRCA 1991 / TPA 1882 / IT Act 2023 / holding tax / NRB) */
function LEGAL_KB() {
    return [
        ['PRCA','Advance cap — residential','PRCA 1991 §10: a residential landlord may not demand more than 1 month\'s rent as advance without the Rent Controller\'s consent. KRTaker flags any residential lease exceeding the cap before revenue can move.','residential advance cap prca 10 one month'],
        ['PRCA','Advance cap — commercial','PRCA 1991 §23: commercial premises advances are capped at 3 months\' rent. Any excess must be returned or adjusted at the tenant\'s demand.','commercial advance cap prca 23 three months'],
        ['PRCA','Rent hike limit','PRCA 1991: for residential premises the monthly rent may not be increased by more than 5% every 3 years without rent-controller approval. Notices must be in writing.','rent hike increase 5 percent three years prca'],
        ['PRCA','Signed receipts','PRCA 1991 §13: the landlord must issue a signed, dated receipt for every rent payment — even partial payments. KRTaker issues a cryptographically signed receipt (PRCA §13) for every payment automatically.','receipt signed prca 13 payment proof'],
        ['PRCA','Eviction protection','PRCA 1991 §18: a tenant may only be evicted on statutory grounds (e.g. 3+ months rent unpaid, owner\'s genuine need, breach of terms) through the Rent Controller. No digital lockouts, utility cuts or self-help evictions are permitted.','eviction protection prca 18 lockout unpaid grounds'],
        ['TPA','Lease registration gate','TPA 1882 §107 & Registration Act 1908 §17(1)(d): any lease for more than 12 months must be registered at the Sub-Registry. Unregistered long leases cannot activate ledgers — KRTaker holds them as Pending Registration.','tpa 107 registration lease 12 months deed sub-registry'],
        ['TPA','Deed checklist','For Sub-Registry registration you need: rent deed (2 copies), tenant NID copy, landlord CS/SA/RS/BS khatian or e-porcha, holding tax paid copies, valuation, stamp duty. KRTaker prepares the checklist automatically.','deed checklist registration documents khatian stamp duty'],
        ['TAX','TDS on rent','Income Tax Act 2023 §109: rent payments attract TDS — 10% on commercial rents and 2% on residential rents paid to individual landlords (verify your exact rate with the current SRO). Withholding is split and tracked per invoice.','tds withholding rent tax 109 commercial 10 residential 2'],
        ['TAX','Capital gains on property','Income Tax Act 2023 §128: gains on transfer of property are taxed at 15%. Wealth surcharge brackets apply above ৳10Cr/৳20Cr slabs. KRTaker\'s estimator computes gain, tax and net proceeds.','capital gain property transfer 128 15 percent surcharge wealth'],
        ['TAX','Minimum tax & surcharge','IT Act 2023 minimum tax applies regardless of losses; wealth surcharge kicks in on taxable income above ৳4Cr (higher slabs at ৳20Cr/৳50Cr+). KRTaker flags minimum-tax cases automatically.','minimum tax wealth surcharge brackets 4cr 20cr 50cr'],
        ['HOLDING','Holding tax formula','Holding tax = NAV × city corporation rate. NAV (Net Annual Value) = Gross Annual Rent × 75% (25% statutory deduction for repairs/collection). GAR → NAV → rate, exactly as KRTaker computes it.','holding tax gar nav annual value rate formula city corporation'],
        ['HOLDING','Dhaka North / South rates','Dhaka North & South city corporations apply their own annual rate on NAV (roughly 5–7%, revised periodically). Holding tax paid copies are required for lease registration and NID address change.','dhaka north south rate holding tax percent'],
        ['KHIATAN','Khatian verification','Land title is verified against CS/SA/RS/BS khatian records and the e-porcha from land.gov.bd. KRTaker cross-references the khatian before onboarding any asset.','khatian cs sa rs bs e-porcha land.gov.bd title verification'],
        ['NRB','Remittance repatriation','NRB landlords repatriate rental income under NRTA/NITA with forms IT10B, Form TM and QA-22. Rental income is taxable in Bangladesh; final-tax treatment depends on your TIN status.','nrb remittance repatriation nrta nita it10b tm qa-22'],
        ['MAINT','Maintenance liability — structural','Structural repairs (roof, external walls, main structure, plumbing mains) are the landlord\'s responsibility under TPA 1882 §108 and standard practice. KRTaker assigns liability Landlord.','maintenance liability structural roof wall landlord tpa 108'],
        ['MAINT','Maintenance liability — tenant','Repairs caused by the tenant\'s use (broken fittings, cosmetic damage, appliance misuse) are the tenant\'s responsibility. KRTaker assigns liability Tenant and can draft the deduction letter.','maintenance liability tenant cosmetic damage fitting'],
        ['MAINT','Common areas & shared systems','Lifts, generators, water pumps, common-area lighting and security are shared liabilities — apportioned across units per lease. KRTaker flags shared liability on tickets.','maintenance liability shared common area lift generator pump'],
        ['PRCA','Rent due & default interest','Rent falls due per the lease (usually the 1st). PRCA does not allow arbitrary late fees; any default interest must be in the written lease. KRTaker tracks due dates and issues compliant reminders.','rent due default late fee reminder prca'],
    ];
}
function legal_seed() {
    $pdo = db();
    $n = (int)$pdo->query('SELECT COUNT(*) FROM legal_docs')->fetchColumn();
    if ($n) return;
    $st = $pdo->prepare('INSERT OR IGNORE INTO legal_docs (cat,title,body,kw) VALUES (?,?,?,?)');
    foreach (LEGAL_KB() as $r) $st->execute([$r[0], $r[1], $r[2], $r[3]]);
    $st2 = $pdo->prepare('INSERT OR IGNORE INTO legal_docs_fts (cat,title,body,kw) VALUES (?,?,?,?)');
    foreach (LEGAL_KB() as $r) $st2->execute([$r[0], $r[1], $r[2], $r[3]]);
}
function legal_search($q) {
    legal_seed();
    $pdo = db();
    $words = preg_split('/\s+/', trim($q));
    $clean = [];
    foreach ($words as $w) { $w = preg_replace('/[^A-Za-z0-9]/', '', $w); if (mb_strlen($w) > 1) $clean[] = strtolower($w); }
    if (!$clean) return [];
    try {
        $fts = '"' . implode('" OR "', array_slice($clean, 0, 6)) . '"';
        $st = $pdo->prepare('SELECT cat,title,body, bm25(legal_docs_fts) AS score FROM legal_docs_fts WHERE legal_docs_fts MATCH ? ORDER BY score LIMIT 3');
        $st->execute([$fts]);
        return $st->fetchAll(PDO::FETCH_ASSOC);
    } catch (Exception $e) {
        $like = '%' . implode('%', $clean) . '%';
        $st = $pdo->prepare('SELECT cat,title,body, 0 AS score FROM legal_docs WHERE body LIKE ? OR title LIKE ? OR kw LIKE ? LIMIT 3');
        $st->execute([$like, $like, $like]);
        return $st->fetchAll(PDO::FETCH_ASSOC);
    }
}

/* ── RBAC-gated tools (permission inheritance: execute AS the calling user) ── */
/* Phase 6: row-level scoping for KR — tenants/partners only see their own records */
function ai_scope($u) {
    if ($u['role'] === 'tenant') {
        $pdo = db();
        /* V2.39: resolve by sub_email (demo) or the tenant's own email */
        $tid = tenant_resolve_id($pdo, $u['email']);
        if (!$tid) return ['leases' => [], 'units' => [], 'invoices' => []];
        $st = $pdo->prepare('SELECT id, u FROM leases WHERE t=?'); $st->execute([$tid]);
        $leases = $st->fetchAll(PDO::FETCH_ASSOC);
        $leaseIds = array_column($leases, 'id');
        $unitIds = array_column($leases, 'u');
        $invIds = [];
        if ($leaseIds) {
            $q = 'SELECT id FROM invoices WHERE l IN (' . implode(',', array_fill(0, count($leaseIds), '?')) . ')';
            $st = $pdo->prepare($q); $st->execute($leaseIds);
            $invIds = $st->fetchAll(PDO::FETCH_COLUMN);
        }
        return ['leases' => $leaseIds, 'units' => $unitIds, 'invoices' => $invIds];
    }
    if ($u['role'] === 'partner') {
        $org = my_org($u);
        $st = db()->prepare('SELECT id FROM tickets WHERE con=?'); $st->execute([$org]);
        return ['leases' => [], 'units' => [], 'invoices' => [], 'tickets' => $st->fetchAll(PDO::FETCH_COLUMN), 'org' => $org];
    }
    return null;   /* staff/owner: org-wide */
}
function ai_in_list($ids) {
    return $ids ? implode(',', array_fill(0, count($ids), '?')) : "''";
}
function ai_q($sql, $args = []) {
    try {
        $st = db()->prepare($sql);
        $st->execute($args);
        return $st->fetchAll(PDO::FETCH_ASSOC);
    } catch (Exception $e) { return []; }
}
/* Parse a month out of a query: YYYY-MM, English or Bengali month name → current year */
function ai_month($q) {
    if (preg_match('/(\d{4})-(\d{2})/', $q, $m)) return $m[1] . '-' . $m[2];
    $bn = ['জানুয়ারি' => 1, 'ফেব্রুয়ারি' => 2, 'মার্চ' => 3, 'এপ্রিল' => 4, 'মে' => 5, 'জুন' => 6, 'জুলাই' => 7, 'আগস্ট' => 8, 'সেপ্টেম্বর' => 9, 'অক্টোবর' => 10, 'নভেম্বর' => 11, 'ডিসেম্বর' => 12];
    $en = ['january' => 1, 'february' => 2, 'march' => 3, 'april' => 4, 'may' => 5, 'june' => 6, 'july' => 7, 'august' => 8, 'september' => 9, 'october' => 10, 'november' => 11, 'december' => 12];
    $s = mb_strtolower($q, 'UTF-8');
    foreach ($bn as $name => $n) { if (mb_strpos($s, $name) !== false) return gmdate('Y') . '-' . str_pad((string)$n, 2, '0', STR_PAD_LEFT); }
    foreach ($en as $name => $n) { if (strpos($s, $name) !== false) return gmdate('Y') . '-' . str_pad((string)$n, 2, '0', STR_PAD_LEFT); }
    return gmdate('Y-m');
}
