/* Phase 11: collections autopilot — unpaid/overdue rollup + reminder engine */
function collections_data($pdo, $limit = 500) {
    $sql = "SELECT i.id AS inv, i.m, i.net, i.status,
                   l.id AS lease, l.rent, u.id AS uid, u.name AS uname, p.id AS pid, p.name AS pname,
                   t.id AS tid, t.name AS tname, t.email AS temail, t.phone AS tphone,
                   COALESCE((SELECT SUM(amount) FROM payments WHERE inv=i.id AND status='Success'),0) AS paid
            FROM invoices i
            JOIN leases l ON l.id=i.l
            JOIN units u ON u.id=l.u
            JOIN properties p ON p.id=u.p
            JOIN tenants t ON t.id=l.t
            WHERE i.status != 'Paid'
            ORDER BY i.m, i.id LIMIT " . (int)$limit;
    $rows = $pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC);
    $out = [];
    foreach ($rows as $r) {
        $due = (int)$r['net'] - (int)$r['paid'];
        if ($due <= 0) continue;
        $out[] = [
            'inv' => $r['inv'], 'm' => $r['m'], 'net' => (int)$r['net'], 'due' => $due, 'status' => $r['status'],
            'unit' => $r['uname'] . ' (' . $r['uid'] . ')', 'property' => $r['pname'],
            'tenant' => $r['tname'], 'email' => $r['temail'], 'phone' => $r['tphone'],
        ];
    }
    return $out;
}
function service_authed() {
    $h = $_SERVER['HTTP_X_SERVICE_KEY'] ?? '';
    return hash_equals(SERVICE_KEY, $h);
}
function collections_email_html($rows) {
    $items = '';
    foreach ($rows as $r) {
        $items .= '<tr><td style="padding:8px 10px;border-bottom:1px solid #E4EAF3;font-size:13px"><b>' . htmlspecialchars($r['inv']) . '</b><br><span style="color:#8A94A6;font-size:11px">' . htmlspecialchars($r['tenant']) . ' · ' . htmlspecialchars($r['property']) . '</span></td>'
            . '<td style="padding:8px 10px;border-bottom:1px solid #E4EAF3;font-size:13px">' . htmlspecialchars($r['m']) . '</td>'
            . '<td style="padding:8px 10px;border-bottom:1px solid #E4EAF3;font-size:13px;text-align:right">৳' . number_format($r['due']) . '</td></tr>';
    }
    $total = array_sum(array_column($rows, 'due'));
    list($s, $h) = email_render('collections', ['unpaid' => count($rows), 'total' => '৳' . number_format($total), 'items' => $items]);
    return $h;
}

/* SA1 v22: rent-due push — owner-facing proactive alert (complements the tenant digest email).
   Classifies each owner's unpaid invoices: overdue (< current month), due_soon (current month),
   upcoming (next N months). Only owners with ≥1 registered push device are considered. */
function rent_due_push_data($pdo, $lookahead = 1) {
    $cur = gmdate('Y-m');
    $monthSet = [];
    for ($i = 1; $i <= max(0, $lookahead); $i++) $monthSet[date('Y-m', strtotime($cur . ' +' . $i . ' months'))] = true;
    $owners = $pdo->query('SELECT DISTINCT sub_email FROM push_subs')->fetchAll(PDO::FETCH_COLUMN);
    $out = [];
    foreach ($owners as $em) {
        if (!$em) continue;
        $st = $pdo->prepare("SELECT i.id AS inv, i.m, i.net,
                COALESCE((SELECT SUM(amount) FROM payments WHERE inv=i.id AND status='Success'),0) AS paid,
                t.name AS tname, u.name AS uname, p.name AS pname
            FROM invoices i
            JOIN leases l ON l.id=i.l
            JOIN units u ON u.id=l.u
            JOIN properties p ON p.id=u.p
            JOIN tenants t ON t.id=l.t
            WHERE p.sub_email=? AND i.status!='Paid'");
        $st->execute([$em]);
        $o = ['email' => $em, 'overdue' => 0, 'due_soon' => 0, 'upcoming' => 0, 'invoices' => 0, 'items' => []];
        foreach ($st->fetchAll(PDO::FETCH_ASSOC) as $r) {
            $due = (int)$r['net'] - (int)$r['paid'];
            if ($due <= 0) continue;
            $it = ['inv' => $r['inv'], 'm' => $r['m'], 'due' => $due, 'tenant' => $r['tname'], 'unit' => $r['uname'], 'property' => $r['pname']];
            if ($r['m'] < $cur) { $o['overdue'] += $due; $it['bucket'] = 'overdue'; }
            elseif ($r['m'] === $cur) { $o['due_soon'] += $due; $it['bucket'] = 'due_soon'; }
            elseif (isset($monthSet[$r['m']])) { $o['upcoming'] += $due; $it['bucket'] = 'upcoming'; }
            else continue; /* outside the window — don't count */
            $o['invoices']++;
            $o['items'][] = $it;
        }
        if ($o['invoices'] > 0) $out[] = $o;
    }
    return $out;
}

/* ════════════════════════════════════════════════════════════════
   Phase 12: document + email templates (customizable, merge fields,
   wireframe field-linking to source records)
