/* Auto-publish CMS pages whose scheduled publish_at time has arrived.
   Idempotent + cheap; call on every CMS read so due pages flip without cron. */
function cms_pub_sweep($pdo) {
    try {
        $pdo->exec("UPDATE cms_pub SET published=1, publish_at=NULL, updated_at=datetime('now')
            WHERE publish_at IS NOT NULL AND publish_at != '' AND publish_at <= datetime('now')");
    } catch (Exception $e) { /* column may not exist on old DBs yet */ }
}
