function legal_notice_meta($ntype) {
    return [
        'eviction'    => ['en' => 'NOTICE TO QUIT', 'bn' => 'উচ্ছেদ নোটিশ', 'ref' => 'Premises Rent Control Act 1991 / PRCO 1985 — statutory notice period', 'days_key' => 'legal_eviction_days'],
        'rent_hike'   => ['en' => 'NOTICE OF RENT INCREASE', 'bn' => 'ভাড়া বৃদ্ধি নোটিশ', 'ref' => 'Premises Rent Control Act 1991 — rent increase notice', 'days_key' => 'legal_rent_hike_days'],
        'termination' => ['en' => 'NOTICE OF LEASE TERMINATION', 'bn' => 'লিজ সমাপ্তি নোটিশ', 'ref' => 'Transfer of Property Act 1882 §106 — termination notice', 'days_key' => 'legal_termination_days'],
        'tds_alert'   => ['en' => 'TDS DEDUCTION ADVISORY', 'bn' => 'টিডিএস কর্তন পরামর্শ', 'ref' => 'Income Tax Act 2023 §109 — TDS on rent', 'days_key' => 'legal_eviction_days'],
    ][$ntype] ?? null;
}
function legal_notice_build($pdo, $ntype, $lease) {
    $meta = legal_notice_meta($ntype);
    $cfg = legal_cfg_all($pdo);
    $days = (int)($cfg[$meta['days_key']] ?? 30);
    $t = tenantById($lease['t']); $u = unitById($lease['u']);
    $tname = $t['name'] ?? 'Tenant'; $uname = $u['name'] ?? $lease['u'];
    $rent = (int)$lease['rent'];
    $eff = date('Y-m-d', strtotime('+' . $days . ' days'));
    $addr = ($t['address'] ?? '') ?: ($t['phone'] ?? '');
    $lines = [];
    $lines[] = $meta['en'] . ' / ' . $meta['bn'];
    $lines[] = 'To: ' . $tname . ' (' . $addr . ')';
    $lines[] = 'Premises: ' . $uname . ' — Lease ' . $lease['id'] . ' (rent ৳' . number_format($rent) . '/month)';
    if ($ntype === 'eviction') {
        $lines[] = 'You are hereby given ' . $days . ' days notice to vacate the premises. Effective date: ' . $eff . '.';
        $lines[] = 'আপনাকে ' . $days . ' দিনের নোটিশ দেওয়া হল — নির্ধারিত তারিখের মধ্যে বাসস্থান খালি করুন। কার্যকর তারিখ: ' . $eff . '।';
    } elseif ($ntype === 'rent_hike') {
        $lines[] = 'Your monthly rent will increase effective ' . $eff . ' (notice period ' . $days . ' days).';
        $lines[] = 'আপনার মাসিক ভাড়া ' . $eff . ' থেকে বৃদ্ধি পাবে (নোটিশ সময়কাল ' . $days . ' দিন)।';
    } elseif ($ntype === 'termination') {
        $lines[] = 'Your lease will terminate effective ' . $eff . ' (notice period ' . $days . ' days). Please prepare for handover.';
        $lines[] = 'আপনার লিজ ' . $eff . ' থেকে সমাপ্ত হবে (নোটিশ সময়কাল ' . $days . ' দিন)। হ্যান্ডওভারের জন্য প্রস্তুত থাকুন।';
    } elseif ($ntype === 'tds_alert') {
        $rate = (int)$cfg['legal_tds_commercial'];
        $lines[] = 'This is a TDS advisory: ' . $rate . '% of gross rent (৳' . number_format(round($rent * $rate / 100)) . '/month) must be withheld and deposited under ITA 2023 §109.';
        $lines[] = 'টিডিএস পরামর্শ: মোট ভাড়ার ' . $rate . '% (মাসিক ৳' . number_format(round($rent * $rate / 100)) . ') কর্তন করে জমা দিতে হবে (আইটিএ ২০২৩ §১০৯)।';
    }
    return ['days' => $days, 'effective' => $eff, 'body' => implode("
", $lines), 'meta' => $meta];
}
function legal_notice_html($n, $lease, $cfg) {
    $meta = legal_notice_meta($n['ntype']);
    $t = tenantById($n['tenant']); $u = unitById($n['unit']);
    $rows = '';
    foreach ([
        ['Notice', $meta['en'] . ' / ' . $meta['bn']],
        ['To', ($t['name'] ?? $n['tenant']) . ($t['phone'] ? ' · ' . $t['phone'] : '')],
        ['Premises', ($u['name'] ?? $n['unit']) . ' — Lease ' . $n['lease']],
        ['Notice period', $n['notice_days'] . ' days'],
        ['Effective date', $n['effective_date']],
        ['Status', $n['status']],
        ['Issued by', $n['created_by']],
        ['Statutory reference', $meta['ref']],
    ] as $r) {
        $rows .= '<tr><td style="padding:8px 12px;border:1px solid #DDE3EC;background:#F7F9FC;font-size:12px;font-weight:700;width:200px">' . $r[0] . '</td><td style="padding:8px 12px;border:1px solid #DDE3EC;font-size:13px">' . esc($r[1]) . '</td></tr>';
    }
    $body = nl2br(esc($n['body']));
    return '<div style="font-family:Arial;max-width:820px;margin:0 auto;padding:20px">'
        . '<div style="margin-bottom:10px">' . print_brand_img() . '</div>'
        . '<div style="border-bottom:3px solid #2F80ED;padding-bottom:12px;margin-bottom:16px"><div style="font-size:20px;font-weight:800">' . esc($meta['en']) . '</div><div style="font-size:12px;color:#667">' . esc($meta['bn']) . ' — ' . esc($meta['ref']) . '</div></div>'
        . '<table style="border-collapse:collapse;width:100%">' . $rows . '</table>'
        . '<div style="margin-top:16px;padding:14px;border:1px solid #E4EAF3;border-radius:8px;background:#FAFCFE;font-size:13px;line-height:1.7">' . $body . '</div></div>';
}
function lease_audit($pdo, $leaseId) {
    $st = $pdo->prepare('SELECT * FROM leases WHERE id=?'); $st->execute([$leaseId]);
    $l = $st->fetch(PDO::FETCH_ASSOC);
    if (!$l) return null;
    $cfg = legal_cfg_all($pdo);
    $rent = (int)$l['rent']; $adv = (int)$l['adv'];
    $isRes = (int)$l['res'] === 1;
    $cap = $isRes ? (int)$cfg['legal_deposit_max_res'] : (int)$cfg['legal_deposit_max_com'];
    $termMonths = 0;
    if ($l['start'] && $l['end']) $termMonths = (int)round((strtotime($l['end']) - strtotime($l['start'])) / 2592000);
    $f = [];
    if ($rent > 0 && $adv > $cap * $rent)
        $f[] = ['sev' => 'high', 'code' => 'DEPOSIT', 'label' => 'Advance exceeds ' . $cap . '× rent', 'detail' => 'Advance ৳' . number_format($adv) . ' > cap ৳' . number_format($cap * $rent) . ' (' . $cap . ' × ৳' . number_format($rent) . ')'];
    if ($termMonths > 12 && empty($l['reg']))
        $f[] = ['sev' => 'high', 'code' => 'REG', 'label' => 'Lease > 12 months must be registered', 'detail' => 'TPA §107 — deed + Sub-Registry stamp duty required'];
    if (!$isRes && empty($l['reg_office']))
        $f[] = ['sev' => 'med', 'code' => 'REGOFF', 'label' => 'Commercial lease missing registration office', 'detail' => 'Set reg_office on the lease record'];
    if (!$isRes)
        $f[] = ['sev' => 'info', 'code' => 'TDS', 'label' => 'TDS obligation on commercial rent', 'detail' => 'Withhold ' . $cfg['legal_tds_commercial'] . '% of gross rent under ITA 2023 §109'];
    if ($l['end'] && strtotime($l['end']) - time() < 60 * 86400 && in_array($l['status'], ['Active', 'Pending Registration'], true))
        $f[] = ['sev' => 'med', 'code' => 'EXP', 'label' => 'Lease ends within 60 days', 'detail' => 'Plan renewal or vacation notice before ' . $l['end']];
    $hi = count(array_filter($f, fn($x) => $x['sev'] === 'high'));
    $me = count(array_filter($f, fn($x) => $x['sev'] === 'med'));
    $score = max(0, 100 - 25 * $hi - 10 * $me);
    return ['lease' => $leaseId, 'tenant' => $l['t'], 'res' => $isRes, 'rent' => $rent, 'adv' => $adv,
        'term_months' => $termMonths, 'status' => $l['status'], 'score' => $score, 'findings' => $f];
}
function tds_due($pdo, $month) {
    $cfg = legal_cfg_all($pdo);
    $rate = (int)$cfg['legal_tds_commercial'];
    $items = []; $total = 0;
    $st = $pdo->query("SELECT l.id AS lease, l.t AS tenant, l.u AS unit, l.rent, t.name AS tenant_name, u.name AS unit_name, p.name AS prop_name
        FROM leases l LEFT JOIN tenants t ON t.id=l.t LEFT JOIN units u ON u.id=l.u LEFT JOIN properties p ON p.id=u.p
        WHERE l.status IN ('Active','Pending Registration') AND l.res=0 ORDER BY l.id");
    foreach ($st->fetchAll(PDO::FETCH_ASSOC) as $r) {
        $gross = (int)$r['rent'];
        $tds = round($gross * $rate / 100);
        $total += $tds;
        $items[] = ['lease' => $r['lease'], 'tenant' => $r['tenant_name'] ?: $r['tenant'], 'unit' => $r['unit_name'] ?: $r['unit'],
            'property' => $r['prop_name'] ?: $r['lease'], 'gross' => $gross, 'rate' => $rate, 'tds' => $tds];
    }
    return ['month' => $month, 'rate' => $rate, 'items' => $items, 'total' => $total];
}
function legal_my_leases($pdo, $u) {
    $tid = tenant_resolve_id($pdo, $u['email']);
    if (!$tid) return [];
    $st = $pdo->prepare('SELECT id FROM leases WHERE t=?');
    $st->execute([$tid]);
    return array_column($st->fetchAll(PDO::FETCH_ASSOC), 'id');
}
function lease_audit_all($pdo) {
    $leases = $pdo->query("SELECT id FROM leases WHERE status IN ('Active','Pending Registration')")->fetchAll(PDO::FETCH_ASSOC);
    $total = 0; $high = 0; $done = [];
    foreach ($leases as $l) {
        $a = lease_audit($pdo, $l['id']);
        if (!$a) continue;
        $total += $a['score'];
        $high += count(array_filter($a['findings'], fn($f) => $f['sev'] === 'high'));
        $done[] = $a;
    }
    return ['count' => count($done), 'total_score' => $total, 'avg' => $done ? (int)round($total / count($done)) : 0, 'high' => $high, 'items' => $done];
}
/* tif print config — per-form override (payload._print) merged over global default (platform_meta tif_print_cfg).
   Defaults reproduce the original pre-settings layout exactly (195mm page, 12.5px, lh 1.15). */
function tif_print_cfg_defaults() {
    return ['fs' => 12.5, 'lh' => 1.15, 'ls' => 0, 'pd' => 0, 'mg' => 7.5, 'px' => 0, 'py' => 0];
}
function tif_print_cfg_global($pdo) {
    $st = $pdo->prepare("SELECT v FROM platform_meta WHERE k='tif_print_cfg'"); $st->execute();
    $v = $st->fetchColumn();
    $g = $v ? (json_decode($v, true) ?: []) : [];
    return array_merge(tif_print_cfg_defaults(), $g);
}
function tif_print_cfg_effective($pdo, $payload) {
    $local = isset($payload['_print']) && is_array($payload['_print']) ? $payload['_print'] : [];
    return array_merge(tif_print_cfg_global($pdo), $local);
}
function tif_print_cfg_sanitize($in) {
    $d = tif_print_cfg_defaults(); $out = [];
    $nums = ['fs', 'lh', 'ls', 'pd', 'mg', 'px', 'py'];
    foreach ($nums as $k) {
        if (!isset($in[$k])) continue;
        $v = (float)$in[$k];
        if ($k === 'fs') $v = max(6, min(40, $v));
        if ($k === 'lh') $v = max(0.5, min(4, $v));
        if ($k === 'ls') $v = max(-5, min(20, $v));
        if ($k === 'pd') $v = max(0, min(30, $v));
        if ($k === 'mg') $v = max(0, min(40, $v));
        if ($k === 'px' || $k === 'py') $v = max(-50, min(50, $v));
        $out[$k] = $v;
    }
    return $out;
}
