    $st = $pdo->prepare('SELECT timeline FROM concierge_requests WHERE id=?'); $st->execute([$id]);
    $tl = json_decode((string)$st->fetchColumn(), true) ?: [];
    $tl[] = ['ts' => date('Y-m-d H:i:s'), 'action' => $action, 'by' => $by];
