        'deep_clean' => ['Vacuum & mop floors', 'Clean kitchen/bathroom', 'Wipe windows', 'Check for mold', 'Pest inspection'],
        'pest_control' => ['Interior spray', 'Perimeter treatment', 'Seal entry points', 'Place traps'],
    ];
