    if ($u['role'] === 'owner') {
        $st = $pdo->prepare("SELECT * FROM fire_incidents WHERE owner_email=? OR owner_email='' ORDER BY ts DESC");
        $st->execute([$u['email']]);
        return $st->fetchAll(PDO::FETCH_ASSOC);
    }
