        $mrows .= '<tr><td>' . htmlspecialchars($m['name']) . '</td><td>' . htmlspecialchars($m['role']) . '</td><td>' . htmlspecialchars($m['phone']) . '</td><td>' . htmlspecialchars($m['since_date']) . '</td><td>' . htmlspecialchars($m['status']) . '</td></tr>';
    }
    $html = '<!DOCTYPE html><html lang="bn"><head><meta charset="utf-8"><title>' . htmlspecialchars($title) . '</title><style>body{font-family:"Noto Sans Bengali",sans-serif;max-width:900px;margin:24px auto;padding:0 16px;color:#1A2332}h1{font-size:20px;margin:0 0 4px}h2{font-size:15px;margin:18px 0 8px;border-bottom:2px solid #E8EDF4;padding-bottom:6px}table{width:100%;border-collapse:collapse;margin:8px 0 18px;font-size:13px}th,td{border:1px solid #E2E8F0;padding:7px 9px;text-align:left}th{background:#F4F7FB}.fund{display:flex;gap:24px;flex-wrap:wrap;margin:12px 0 20px}.fc{background:#F4F7FB;border:1px solid #E2E8F0;border-radius:10px;padding:12px 18px;flex:1;min-width:150px}.fc b{display:block;font-size:18px;margin-top:2px}.sig{display:flex;justify-content:space-between;margin-top:48px;font-size:13px}.sig div{text-align:center;width:42%}.sig .ln{border-top:1px solid #999;padding-top:6px;margin-top:34px}.muted{color:#6B7A90;font-size:12px}</style></head><body>';
    $html .= '<h1>' . htmlspecialchars($title) . '</h1><div class="muted">' . $today . ' · KRTaker Kalyan Samity</div>';
    $html .= '<div class="fund"><div class="fc">' . htmlspecialchars($cfg['t_total_billed'] ?? 'Total billed') . '<b>৳' . number_format($fund['total_billed']) . '</b></div><div class="fc">' . htmlspecialchars($cfg['t_collected'] ?? 'Collected') . '<b>৳' . number_format($fund['total_collected']) . '</b></div><div class="fc">' . htmlspecialchars($cfg['t_outstanding'] ?? 'Outstanding') . '<b>৳' . number_format($fund['outstanding']) . '</b></div><div class="fc">' . htmlspecialchars($cfg['t_rate'] ?? 'Collection rate') . '<b>' . $fund['collection_rate'] . '%</b></div></div>';
    $html .= '<h2>' . htmlspecialchars($cfg['t_committee'] ?? 'Committee') . '</h2><table><thead><tr><th>Name</th><th>Role</th><th>Phone</th><th>Since</th><th>Status</th></tr></thead><tbody>' . $mrows . '</tbody></table>';
    $html .= '<h2>' . htmlspecialchars($cfg['t_charges'] ?? 'Service charge ledger') . '</h2><table><thead><tr><th>Unit</th><th>Month</th><th>Billed</th><th>Collected</th><th>Outstanding</th><th>Status</th></tr></thead><tbody>' . $rows . '</tbody></table>';
    $html .= '<div class="sig"><div><div class="ln">Chairman / সভাপতি</div></div><div><div class="ln">Treasurer / কোষাধ্যক্ষ</div></div></div>';
    $html .= '</body></html>';
    return $html;
}
function kr_alert_scan($pdo) {
    /* SLA breaches + at-risk from maintenance */
    $sla = sla_summary($pdo);
    $created = 0;
    /* fan out to all active owners (subscribers) so each gets their own alert queue */
    $owners = [];
    $ost = $pdo->query("SELECT id FROM subscribers WHERE status='active' ORDER BY id");
    foreach ($ost->fetchAll(PDO::FETCH_ASSOC) as $o) $owners[] = 'sub:' . $o['id'];
    if (!$owners) $owners[] = 'sub:1';
    /* V2.23: fan the GENERIC alert types (SLA/compliance/arrears/renewals) out to
       active staff app_users too (staff:<id> user keys) — previously ops staff
       (manager/svc_mgr/legal/hr/accountant) saw no alerts at all. Owner-specific
       alerts (land parcels, NRB vacancies/disputes) stay targeted to the parcel
       owner's subscriber key below. */
    $staff = [];
    $sst = $pdo->query("SELECT id FROM app_users WHERE active=1 AND is_staff=1 ORDER BY id");
    foreach ($sst->fetchAll(PDO::FETCH_ASSOC) as $s) $staff[] = 'staff:' . $s['id'];
    $targets = array_merge($owners, $staff);
    foreach ($sla['items'] as $it) {
        if ($it['status'] !== 'breached' && $it['status'] !== 'at_risk') continue;
        $sev = $it['status'] === 'breached' ? 'critical' : 'warning';
        $label = $it['status'] === 'breached' ? 'SLA breached' : 'SLA at risk';
        $body = $it['id'] . ' · ' . $it['title'] . ' · ' . $it['priority'] . ' priority · elapsed ' . $it['elapsed_hours'] . 'h';
        foreach ($targets as $ukOwner) if (kr_alert_upsert($pdo, $ukOwner, 'sla', $sev, $label, $body, $it['id']) !== null) $created++;
    }
    /* compliance expiries within 45 days */
    $today = date('Y-m-d');
    foreach ($pdo->query('SELECT * FROM compliance_items WHERE expiry_date>=\'\' ORDER BY expiry_date')->fetchAll(PDO::FETCH_ASSOC) as $c) {
        if (!$c['expiry_date'] || $c['expiry_date'] > date('Y-m-d', strtotime('+45 days'))) continue;
        $sev = $c['expiry_date'] < $today ? 'critical' : 'warning';
        $label = $c['expiry_date'] < $today ? 'Compliance expired' : 'Compliance expiring';
        foreach ($targets as $ukOwner) if (kr_alert_upsert($pdo, $ukOwner, 'compliance', $sev, $label, $c['label'] . ' · ' . $c['entity_id'] . ' · ' . $c['expiry_date'], $c['id']) !== null) $created++;
    }
    /* arrears — unpaid invoices older than 7 days */
    $st = $pdo->query("SELECT i.id, i.l, i.m, i.net, l.t FROM invoices i JOIN leases l ON l.id=i.l WHERE i.status!='Paid' AND i.m < date('now','-7 days')");
    foreach ($st->fetchAll(PDO::FETCH_ASSOC) as $i) {
        $tst = $pdo->prepare('SELECT name FROM tenants WHERE id=?'); $tst->execute([$i['t']]);
        $tname = (string)$tst->fetchColumn();
        foreach ($targets as $ukOwner) if (kr_alert_upsert($pdo, $ukOwner, 'arrears', 'critical', 'Rent arrears', $i['id'] . ' · ' . $tname . ' · ' . $i['m'] . ' · ৳' . number_format($i['net']), $i['id']) !== null) $created++;
    }
    /* renewals within 60 days */
    $st = $pdo->query("SELECT l.id, l.end, l.rent, t.name AS tname, u.name AS uname FROM leases l JOIN tenants t ON t.id=l.t JOIN units u ON u.id=l.u WHERE l.status='Active' AND l.end <= date('now','+60 days') AND l.end >= date('now')");
    foreach ($st->fetchAll(PDO::FETCH_ASSOC) as $l) {
        foreach ($targets as $ukOwner) if (kr_alert_upsert($pdo, $ukOwner, 'renewal', 'warning', 'Lease renewal due', $l['id'] . ' · ' . $l['tname'] . ' · ' . $l['uname'] . ' · ends ' . $l['end'], $l['id']) !== null) $created++;
    }
    /* land guard — encroached parcels, overdue/due-soon visits (NRB owner parcels only) */
    $landRows = $pdo->query('SELECT * FROM land_parcels ORDER BY ts DESC')->fetchAll(PDO::FETCH_ASSOC);
    foreach ($landRows as $lpRow) {
        if (trim($lpRow['owner_email'] ?? '') === '') continue;
        $ost = $pdo->prepare("SELECT id FROM subscribers WHERE email=? AND status='active'"); $ost->execute([$lpRow['owner_email']]);
        $subId = $ost->fetchColumn();
        if (!$subId) continue;
        $e = land_enrich($pdo, [$lpRow])[0];
        if ($e['status'] === 'Encroached') {
            foreach (['sub:' . $subId] as $ukOwner) if (kr_alert_upsert($pdo, $ukOwner, 'land', 'critical', 'Encroachment detected', $e['name'] . ' (' . $e['id'] . ') — verify and take action', $e['id']) !== null) $created++;
        } elseif ($e['due_days'] !== null && $e['due_days'] < 0) {
            foreach (['sub:' . $subId] as $ukOwner) if (kr_alert_upsert($pdo, $ukOwner, 'land', 'warning', 'Land visit overdue', $e['name'] . ' (' . $e['id'] . ') — monitoring visit ' . abs($e['due_days']) . 'd overdue', $e['id']) !== null) $created++;
        } elseif ($e['due_days'] !== null && $e['due_days'] <= 14) {
            foreach (['sub:' . $subId] as $ukOwner) if (kr_alert_upsert($pdo, $ukOwner, 'land', 'info', 'Land visit due soon', $e['name'] . ' (' . $e['id'] . ') — next visit in ' . $e['due_days'] . 'd', $e['id']) !== null) $created++;
        }
    }

    /* nrb hub — vacancy awaiting approval >2d, vacant 30d+, disputes open 14d+ (NRB owners) */
    $vacRows = $pdo->query('SELECT * FROM nrb_vacancies ORDER BY ts DESC')->fetchAll(PDO::FETCH_ASSOC);
    foreach ($vacRows as $vcRow) {
        if (trim($vcRow['owner_email'] ?? '') === '') continue;
        $ost = $pdo->prepare("SELECT id FROM subscribers WHERE email=? AND status='active'"); $ost->execute([$vcRow['owner_email']]);
        $subId = $ost->fetchColumn();
        if (!$subId) continue;
        $ukOwner = 'sub:' . $subId;
        if ($vcRow['status'] === 'Awaiting_Approval' && $vcRow['updated_at'] && strtotime($vcRow['updated_at']) < strtotime('-2 days')) {
            if (kr_alert_upsert($pdo, $ukOwner, 'nrb', 'warning', 'Vacancy awaiting your approval', $vcRow['id'] . ' — ' . $vcRow['unit'] . ' · approve to sign the lease', $vcRow['id']) !== null) $created++;
        } elseif (in_array($vcRow['status'], ['Vacant', 'Marketing', 'Showing', 'Vetting'], true) && $vcRow['ts'] && strtotime($vcRow['ts']) < strtotime('-30 days')) {
            if (kr_alert_upsert($pdo, $ukOwner, 'nrb', 'info', 'Vacancy needs attention', $vcRow['id'] . ' — empty 30+ days · start marketing', $vcRow['id']) !== null) $created++;
        }
    }
    $dRows = $pdo->query('SELECT * FROM nrb_disputes ORDER BY ts DESC')->fetchAll(PDO::FETCH_ASSOC);
    foreach ($dRows as $dRow) {
        if (trim($dRow['owner_email'] ?? '') === '') continue;
        $ost = $pdo->prepare("SELECT id FROM subscribers WHERE email=? AND status='active'"); $ost->execute([$dRow['owner_email']]);
        $subId = $ost->fetchColumn();
        if (!$subId) continue;
        if (!in_array($dRow['status'], ['Resolved', 'Closed'], true) && $dRow['ts'] && strtotime($dRow['ts']) < strtotime('-14 days')) {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'nrb', 'warning', 'Dispute open 14+ days', $dRow['id'] . ' — ' . $dRow['dtype'] . ' · ' . $dRow['tenant'], $dRow['id']) !== null) $created++;
        }
    }
    /* legal concierge — requests stuck / fees pending / holding taxes due (owners) */
    $crAll = $pdo->query('SELECT * FROM concierge_requests ORDER BY ts DESC')->fetchAll(PDO::FETCH_ASSOC);
    $ccfg = concierge_config_rows($pdo);
    foreach ($crAll as $crRow) {
        if (trim($crRow['owner_email'] ?? '') === '') continue;
        $ost = $pdo->prepare("SELECT id FROM subscribers WHERE email=? AND status='active'"); $ost->execute([$crRow['owner_email']]);
        $subId = $ost->fetchColumn();
        if (!$subId) continue;
        $ukOwner = 'sub:' . $subId;
        if ($crRow['status'] === 'Awaiting_Fee' && $crRow['fee_status'] !== 'paid' && $crRow['awaiting_fee_at'] && strtotime($crRow['awaiting_fee_at']) < strtotime('-7 days')) {
            if (kr_alert_upsert($pdo, $ukOwner, 'concierge', 'warning', 'Concierge fee pending', $crRow['id'] . ' — ' . str_replace('_', ' ', $crRow['service']) . ' · ৳' . number_format($crRow['fee']) . ' · mark fee paid to continue', $crRow['id']) !== null) $created++;
        } elseif (in_array($crRow['status'], ['Under_Review', 'Docs_Requested', 'In_Progress'], true) && $crRow['updated_at'] && strtotime($crRow['updated_at']) < strtotime('-' . (int)$ccfg['docs_stuck_days'] . ' days')) {
            if (kr_alert_upsert($pdo, $ukOwner, 'concierge', 'info', 'Concierge request in progress', $crRow['id'] . ' — ' . str_replace('_', ' ', $crRow['service']) . ' · no update in ' . (int)$ccfg['docs_stuck_days'] . 'd', $crRow['id']) !== null) $created++;
        }
    }
    $htAll = $pdo->query('SELECT * FROM holding_taxes ORDER BY ts DESC')->fetchAll(PDO::FETCH_ASSOC);
    foreach ($htAll as $htRow) {
        if (trim($htRow['owner_email'] ?? '') === '') continue;
        if ($htRow['status'] === 'Paid') continue;
        $ost = $pdo->prepare("SELECT id FROM subscribers WHERE email=? AND status='active'"); $ost->execute([$htRow['owner_email']]);
        $subId = $ost->fetchColumn();
        if (!$subId) continue;
        $ukOwner = 'sub:' . $subId;
        if ($htRow['due_date'] && $htRow['due_date'] < date('Y-m-d')) {
            if (kr_alert_upsert($pdo, $ukOwner, 'concierge', 'warning', 'Holding tax overdue', $htRow['id'] . ' — ' . ($htRow['city_corp'] ?: 'City Corp') . ' · ' . $htRow['holding_no'] . ' · ৳' . number_format($htRow['tax_amount']), $htRow['id']) !== null) $created++;
        } elseif ($htRow['due_date'] && $htRow['due_date'] <= date('Y-m-d', strtotime('+' . (int)$ccfg['holding_alert_days'] . ' days'))) {
            if (kr_alert_upsert($pdo, $ukOwner, 'concierge', 'info', 'Holding tax due soon', $htRow['id'] . ' — ' . ($htRow['city_corp'] ?: 'City Corp') . ' · ' . $htRow['holding_no'] . ' · due ' . $htRow['due_date'], $htRow['id']) !== null) $created++;
        }
    }
    /* smart home — cameras offline 24h+, active lock codes expiring within 48h */
    $cvAll = $pdo->query('SELECT * FROM cctv_cameras ORDER BY ts DESC')->fetchAll(PDO::FETCH_ASSOC);
    foreach ($cvAll as $cvRow) {
        if (trim($cvRow['owner_email'] ?? '') === '') continue;
        if ($cvRow['status'] !== 'offline') continue;
        $last = $cvRow['last_seen'] ?: $cvRow['ts'];
        if (!$last || strtotime($last) >= strtotime('-24 hours')) continue;
        $ost = $pdo->prepare("SELECT id FROM subscribers WHERE email=? AND status='active'"); $ost->execute([$cvRow['owner_email']]);
        $subId = $ost->fetchColumn();
        if (!$subId) continue;
        if (kr_alert_upsert($pdo, 'sub:' . $subId, 'smarthome', 'warning', 'Camera offline', $cvRow['id'] . ' — ' . ($cvRow['name'] ?: 'camera') . ' · ' . ($cvRow['location'] ?: '') . ' · no signal 24h+', $cvRow['id']) !== null) $created++;
    }
    $slAll = $pdo->query("SELECT * FROM smart_locks WHERE status='active' ORDER BY ts DESC")->fetchAll(PDO::FETCH_ASSOC);
    foreach ($slAll as $slRow) {
        if (trim($slRow['owner_email'] ?? '') === '') continue;
        if (!$slRow['valid_until'] || strtotime($slRow['valid_until']) > strtotime('+48 hours')) continue;
        $ost = $pdo->prepare("SELECT id FROM subscribers WHERE email=? AND status='active'"); $ost->execute([$slRow['owner_email']]);
        $subId = $ost->fetchColumn();
        if (!$subId) continue;
        if (kr_alert_upsert($pdo, 'sub:' . $subId, 'smarthome', 'info', 'Lock code expiring soon', $slRow['id'] . ' — ' . ($slRow['lock_name'] ?: 'lock') . ' · expires ' . $slRow['valid_until'], $slRow['id']) !== null) $created++;
    }
    /* health check — plans overdue / due within the alert window */
    $hpAll = $pdo->query('SELECT * FROM health_plans ORDER BY ts DESC')->fetchAll(PDO::FETCH_ASSOC);
    $thisMonth = date('Y-m');
    $nextMonth = date('Y-m', strtotime('+1 month'));
    foreach ($hpAll as $hpRow) {
        if (trim($hpRow['owner_email'] ?? '') === '') continue;
        if (in_array($hpRow['status'], ['Completed', 'Skipped'], true)) continue;
        $ost = $pdo->prepare("SELECT id FROM subscribers WHERE email=? AND status='active'"); $ost->execute([$hpRow['owner_email']]);
        $subId = $ost->fetchColumn();
        if (!$subId) continue;
        $label = $hpRow['service'] . ' · ' . ($hpRow['prop'] ?: '—') . ($hpRow['unit'] ? ' · ' . $hpRow['unit'] : '') . ' · ' . $hpRow['scheduled_for'];
        if ($hpRow['scheduled_for'] && $hpRow['scheduled_for'] < $thisMonth) {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'health', 'warning', 'Health check overdue', $hpRow['id'] . ' — ' . str_replace('_', ' ', $label), $hpRow['id']) !== null) $created++;
        } elseif ($hpRow['scheduled_for'] && $hpRow['scheduled_for'] <= $nextMonth) {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'health', 'info', 'Health check due', $hpRow['id'] . ' — ' . str_replace('_', ' ', $label) . ' · ' . $hpRow['scheduled_for'], $hpRow['id']) !== null) $created++;
        }
    }
    /* build watch — milestone overdue / budget overrun (email-owned projects) */
    $bpAll = $pdo->query('SELECT * FROM build_projects ORDER BY ts DESC')->fetchAll(PDO::FETCH_ASSOC);
    foreach (bp_enrich($pdo, $bpAll) as $bpRow) {
        if (trim($bpRow['owner_email'] ?? '') === '') continue;
        $ost = $pdo->prepare("SELECT id FROM subscribers WHERE email=? AND status='active'"); $ost->execute([$bpRow['owner_email']]);
        $subId = $ost->fetchColumn();
        if (!$subId) continue;
        if ((int)$bpRow['milestones_overdue'] > 0) {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'build', 'warning', 'Build milestone overdue', $bpRow['id'] . ' — ' . $bpRow['title'] . ' · ' . $bpRow['milestones_overdue'] . ' past due', $bpRow['id'] . '-od') !== null) $created++;
        }
        if (!empty($bpRow['over_budget'])) {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'build', 'warning', 'Build budget overrun', $bpRow['id'] . ' — ' . $bpRow['title'] . ' · spent ৳' . number_format($bpRow['spent']) . ' vs ৳' . number_format((int)$bpRow['budget_total']) . ' budget', $bpRow['id'] . '-bg') !== null) $created++;
        }
    }
    /* gate watch — flagged watchlist visitor on site (critical) + long-stay (warning) */
    $gvRows = $pdo->query("SELECT * FROM gate_visits WHERE status='Inside' ORDER BY ts DESC")->fetchAll(PDO::FETCH_ASSOC);
    foreach ($gvRows as $gv) {
        $oemail = (string)($gv['owner_email'] ?? '');
        if (trim($oemail) === '') continue;
        $ost = $pdo->prepare("SELECT id FROM subscribers WHERE email=? AND status='active'"); $ost->execute([$oemail]);
        $subId = $ost->fetchColumn();
        if (!$subId) continue;
        $pname = '';
        if ($gv['prop']) { $pt = $pdo->prepare('SELECT name FROM properties WHERE id=?'); $pt->execute([$gv['prop']]); $pn = $pt->fetchColumn(); $pname = $pn ?: $gv['prop']; }
        $who = $gv['name'] !== '' ? $gv['name'] : ($gv['vehicle_no'] !== '' ? $gv['vehicle_no'] : $gv['id']);
        if ((int)$gv['flagged'] === 1) {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'gate', 'critical', 'Watchlist visitor on site', $gv['id'] . ' — ' . $who . ' · ' . $pname . ' · FLAGGED', $gv['id'] . '-wl') !== null) $created++;
        }
        if ($gv['check_in'] && (time() - strtotime($gv['check_in'])) / 3600 >= (int)(gate_cfg($pdo, 'auto_flag_hours', 4))) {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'gate', 'warning', 'Long-stay visitor', $gv['id'] . ' — ' . $who . ' still inside after ' . (int)((time() - strtotime($gv['check_in'])) / 3600) . 'h · ' . $pname, $gv['id'] . '-ls') !== null) $created++;
        }
    }
    /* fire safety — expired/expiring/faulty assets, overdue inspections, open high incidents, drills (owners) */
    $faAll = fire_asset_enrich($pdo, $pdo->query('SELECT * FROM fire_assets ORDER BY ts DESC')->fetchAll(PDO::FETCH_ASSOC));
    foreach ($faAll as $fa) {
        if (trim($fa['owner_email'] ?? '') === '') continue;
        $ost = $pdo->prepare("SELECT id FROM subscribers WHERE email=? AND status='active'"); $ost->execute([$fa['owner_email']]);
        $subId = $ost->fetchColumn();
        if (!$subId) continue;
        $albl = $fa['asset_type_label'] . ' · ' . ($fa['location'] ?: '—') . ' · ' . ($fa['property_name'] ?: $fa['prop']);
        if ((int)$fa['expired'] === 1) {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'firesafety', 'critical', 'Fire asset expired', $fa['id'] . ' — ' . $albl . ' · expired ' . $fa['expiry_date'] . ' · replace or recharge', $fa['id'] . '-ex') !== null) $created++;
        } elseif ((int)$fa['expiring'] === 1) {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'firesafety', 'warning', 'Fire asset expiring soon', $fa['id'] . ' — ' . $albl . ' · expires in ' . $fa['days_to_expiry'] . 'd', $fa['id'] . '-ew') !== null) $created++;
        }
        if ($fa['status'] === 'faulty') {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'firesafety', 'warning', 'Fire asset faulty', $fa['id'] . ' — ' . $albl . ' · needs service', $fa['id'] . '-fy') !== null) $created++;
        }
        if ((int)$fa['inspection_overdue'] === 1) {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'firesafety', 'info', 'Fire inspection overdue', $fa['id'] . ' — ' . $albl . ' · due ' . $fa['next_inspection'], $fa['id'] . '-in') !== null) $created++;
        }
    }
    $fiAll = fire_incident_enrich($pdo, $pdo->query('SELECT * FROM fire_incidents ORDER BY ts DESC')->fetchAll(PDO::FETCH_ASSOC));
    foreach ($fiAll as $fi) {
        if (trim($fi['owner_email'] ?? '') === '') continue;
        if (in_array($fi['status'], ['Resolved', 'Closed'], true)) continue;
        if (!in_array($fi['severity'], ['high', 'critical'], true)) continue;
        $ost = $pdo->prepare("SELECT id FROM subscribers WHERE email=? AND status='active'"); $ost->execute([$fi['owner_email']]);
        $subId = $ost->fetchColumn();
        if (!$subId) continue;
        if (kr_alert_upsert($pdo, 'sub:' . $subId, 'firesafety', 'warning', 'Open fire incident', $fi['id'] . ' — ' . ucfirst($fi['incident_type']) . ' · ' . $fi['severity'] . ' · ' . ($fi['location'] ?: '') . ' · ' . $fi['status'], $fi['id']) !== null) $created++;
    }
    $epAll = fire_plan_enrich($pdo, $pdo->query("SELECT * FROM evacuation_plans WHERE status='active' ORDER BY ts DESC")->fetchAll(PDO::FETCH_ASSOC));
    foreach ($epAll as $ep) {
        if (trim($ep['owner_email'] ?? '') === '') continue;
        if (!$ep['next_drill'] || $ep['next_drill'] >= date('Y-m-d')) continue;
        $ost = $pdo->prepare("SELECT id FROM subscribers WHERE email=? AND status='active'"); $ost->execute([$ep['owner_email']]);
        $subId = $ost->fetchColumn();
        if (!$subId) continue;
        if (kr_alert_upsert($pdo, 'sub:' . $subId, 'firesafety', 'info', 'Evacuation drill overdue', $ep['id'] . ' — ' . ($ep['name'] ?: 'plan') . ' · ' . ($ep['property_name'] ?: $ep['prop']) . ' · due ' . $ep['next_drill'], $ep['id'] . '-dr') !== null) $created++;
    }
    /* systems watch — cert/service/fuel alerts (owners) */
    $saRows = $pdo->query('SELECT * FROM sys_assets ORDER BY ts DESC')->fetchAll(PDO::FETCH_ASSOC);
    $saEnr = sys_asset_enrich($pdo, $saRows);
    $subCache = [];
    foreach ($saEnr as $sa) {
        if ($sa['owner_email'] === '') continue;
        if (!isset($subCache[$sa['owner_email']])) {
            $st = $pdo->prepare("SELECT id FROM subscribers WHERE email=? AND status='active'"); $st->execute([$sa['owner_email']]);
            $subCache[$sa['owner_email']] = $st->fetchColumn();
        }
        $subId = $subCache[$sa['owner_email']];
        if (!$subId) continue;
        $albl = $sa['asset_type_label'];
        if ((int)$sa['cert_overdue']) {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'systems', 'critical', 'Certificate expired', $sa['id'] . ' — ' . $albl . ' · ' . ($sa['cert_ref'] ?: '') . ' · expired ' . $sa['cert_expiry'] . ' · renew', $sa['id'] . '-ce') !== null) $created++;
        } elseif ((int)$sa['cert_expiring']) {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'systems', 'warning', 'Certificate expiring soon', $sa['id'] . ' — ' . $albl . ' · ' . ($sa['cert_ref'] ?: '') . ' · expires ' . $sa['cert_expiry'], $sa['id'] . '-cw') !== null) $created++;
        }
        if ((int)$sa['service_overdue']) {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'systems', 'warning', 'Service overdue', $sa['id'] . ' — ' . $albl . ' · due ' . $sa['next_service'], $sa['id'] . '-so') !== null) $created++;
        } elseif ((int)$sa['service_due_soon']) {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'systems', 'info', 'Service due soon', $sa['id'] . ' — ' . $albl . ' · by ' . $sa['next_service'], $sa['id'] . '-sd') !== null) $created++;
        }
        if ($sa['status'] === 'faulty') {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'systems', 'warning', 'System faulty', $sa['id'] . ' — ' . $albl . ' · needs service', $sa['id'] . '-fy') !== null) $created++;
        }
        if ((int)$sa['fuel_low']) {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'systems', 'warning', 'Generator fuel low', $sa['id'] . ' — ' . $albl . ' · ' . $sa['fuel_pct'] . '% (' . $sa['fuel_level'] . '/' . $sa['fuel_capacity'] . 'L) · refill before next load shed', $sa['id'] . '-fl') !== null) $created++;
        }
    }
    /* staff watch — attendance/payroll alerts (owners) */
    $bsRows = $pdo->query("SELECT * FROM building_staff WHERE status IN ('active','on_leave') ORDER BY ts DESC")->fetchAll(PDO::FETCH_ASSOC);
    $bsEnr = staff_enrich($pdo, $bsRows);
    $subCache3 = [];
    $bsAbsentPct = (int)(staff_cfg($pdo, 'absent_pct', 30));
    $bsAlertDays = (int)(staff_cfg($pdo, 'payroll_alert_days', 7));
    $bsDayOfMonth = (int)date('j');
    foreach ($bsEnr as $bs) {
        if ($bs['owner_email'] === '') continue;
        if (!isset($subCache3[$bs['owner_email']])) {
            $st = $pdo->prepare("SELECT id FROM subscribers WHERE email=? AND status='active'"); $st->execute([$bs['owner_email']]);
            $subCache3[$bs['owner_email']] = $st->fetchColumn();
        }
        $subId = $subCache3[$bs['owner_email']];
        if (!$subId) continue;
        if ($bs['status'] === 'active' && $bs['today_status'] === '') {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'staffwatch', 'info', 'Attendance not marked', $bs['id'] . ' — ' . $bs['name'] . ' · ' . date('Y-m-d'), $bs['id'] . '-at') !== null) $created++;
        }
        if ($bs['status'] === 'active' && $bs['absent_pct'] >= $bsAbsentPct) {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'staffwatch', 'warning', 'High absenteeism', $bs['id'] . ' — ' . $bs['name'] . ' · ' . $bs['absent_pct'] . '% absent this month', $bs['id'] . '-ab') !== null) $created++;
        }
        if ((int)$bs['payroll_unpaid_prev'] && $bsDayOfMonth > $bsAlertDays) {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'staffwatch', 'warning', 'Salary due', $bs['id'] . ' — ' . $bs['name'] . ' · ' . date('Y-m', strtotime('-1 month')) . ' payroll unpaid', $bs['id'] . '-py') !== null) $created++;
        }
    }
    /* kalyan samity — service-charge alerts (owners) */
    $smBills = $pdo->query('SELECT * FROM samity_bills ORDER BY ts DESC')->fetchAll(PDO::FETCH_ASSOC);
    $smEnr = array_map(fn($b) => samity_bill_enrich($pdo, $b), $smBills);
    $smAlertDays = (int)(samity_cfg($pdo, 'alert_days', 7));
    $subCache4 = [];
    foreach ($smEnr as $sb) {
        if ($sb['owner_email'] === '') continue;
        if (!isset($subCache4[$sb['owner_email']])) {
            $st = $pdo->prepare("SELECT id FROM subscribers WHERE email=? AND status='active'"); $st->execute([$sb['owner_email']]);
            $subCache4[$sb['owner_email']] = $st->fetchColumn();
        }
        $subId = $subCache4[$sb['owner_email']];
        if (!$subId) continue;
        if ($sb['overdue']) {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'samity', 'warning', 'Service charge overdue', $sb['unit_label'] . ' · ' . $sb['month'] . ' — ৳' . number_format($sb['outstanding']) . ' due', $sb['id'] . '-ov') !== null) $created++;
        } elseif ($sb['computed_status'] !== 'Waived' && $sb['due_date'] !== '' && $sb['due_date'] <= date('Y-m-d', strtotime('+' . $smAlertDays . ' days'))) {
            if (kr_alert_upsert($pdo, 'sub:' . $subId, 'samity', 'info', 'Service charge due soon', $sb['unit_label'] . ' · ' . $sb['month'] . ' — due ' . $sb['due_date'], $sb['id'] . '-sd') !== null) $created++;
        }
    }
    return $created;
}

function wa_channel_for($pdo, $userKey) {
    $st = $pdo->prepare("SELECT * FROM wa_channels WHERE user_key=? AND status='active' AND LENGTH(phone)>=9 ORDER BY ts DESC LIMIT 1");
    $st->execute([$userKey]);
    return $st->fetch(PDO::FETCH_ASSOC) ?: null;
}
/* ---------- Phase 41: portfolio analytics & forecasting helpers ---------- */
function analytics_pnl($pdo, $month, $scope = '') {
    $props = $pdo->query('SELECT id, name, type FROM properties' . ($scope ? ' WHERE sub_email=' . $pdo->quote($scope) : '') . ' ORDER BY id')->fetchAll(PDO::FETCH_ASSOC);
    $rows = []; $tot = ['gross' => 0, 'collected' => 0, 'tds' => 0, 'service' => 0, 'expenses' => 0, 'net' => 0];
    foreach ($props as $p) {
        $c = statement_calc($pdo, $p['id'], $month);
        $row = ['prop' => $p['id'], 'name' => $p['name'], 'type' => $p['type'],
            'gross' => $c['gross'], 'collected' => $c['collected'], 'tds' => $c['tds'],
            'service' => $c['service'], 'expenses' => $c['expenses'], 'net' => $c['net']];
        $rows[] = $row;
        foreach ($tot as $k => $v) $tot[$k] += $row[$k];
    }
    return ['month' => $month, 'properties' => $rows, 'totals' => $tot];
}
function analytics_trends($pdo, $months = 12, $scope = '') {
    $out = []; $cur = new DateTime(date('Y-m-01'));
    $sc = $scope ? ' AND l IN (SELECT l.id FROM leases l JOIN units u ON u.id=l.u WHERE u.sub_email=' . $pdo->quote($scope) . ')' : '';
    for ($i = $months - 1; $i >= 0; $i--) {
        $m = (clone $cur)->modify("-{$i} months")->format('Y-m');
        $is = $pdo->prepare('SELECT COALESCE(SUM(net),0) FROM invoices WHERE m=?' . $sc); $is->execute([$m]);
        $cs = $pdo->prepare('SELECT COALESCE(SUM(p.amount),0) FROM payments p JOIN invoices i ON i.id=p.inv WHERE i.m=?' . $sc . ' AND p.status=\'Success\''); $cs->execute([$m]);
        $out[] = ['month' => $m, 'issued' => (int)$is->fetchColumn(), 'collected' => (int)$cs->fetchColumn()];
    }
    $units = (int)$pdo->query('SELECT COUNT(*) FROM units' . ($scope ? ' WHERE sub_email=' . $pdo->quote($scope) : ''))->fetchColumn();
    $leased = (int)$pdo->query('SELECT COUNT(*) FROM units' . ($scope ? ' WHERE sub_email=' . $pdo->quote($scope) . ' AND status=\'Leased\'' : " WHERE status='Leased'"))->fetchColumn();
    return ['months' => $out, 'units' => $units, 'leased' => $leased, 'occupancy' => $units ? round($leased / $units * 100) : 0];
}
function analytics_aging($pdo, $scope = '') {
    $cur = date('Y-m');
    $curY = (int)substr($cur, 0, 4); $curM = (int)substr($cur, 5, 2);
    $buckets = ['current' => 0, 'd30' => 0, 'd60' => 0, 'd90' => 0];
    $sc = $scope ? ' AND l IN (SELECT l.id FROM leases l JOIN units u ON u.id=l.u WHERE u.sub_email=' . $pdo->quote($scope) . ')' : '';
    $rows = $pdo->query("SELECT m, net FROM invoices WHERE status!='Paid'" . $sc)->fetchAll(PDO::FETCH_ASSOC);
    foreach ($rows as $r) {
        $y = (int)substr($r['m'], 0, 4); $mo = (int)substr($r['m'], 5, 2);
        $age = ($curY - $y) * 12 + ($curM - $mo);
        if ($age <= 0) $buckets['current'] += (int)$r['net'];
        elseif ($age === 1) $buckets['d30'] += (int)$r['net'];
        elseif ($age === 2) $buckets['d60'] += (int)$r['net'];
        else $buckets['d90'] += (int)$r['net'];
    }
    $buckets['total'] = array_sum($buckets);
    return $buckets;
}
function analytics_vacancy($pdo, $scope = '') {
    $sc = $scope ? ' WHERE u.sub_email=' . $pdo->quote($scope) . ' AND u.status=\'Vacant\'' : " WHERE u.status='Vacant'";
    $rows = $pdo->query("SELECT u.id, u.name, u.rent, p.name AS prop FROM units u LEFT JOIN properties p ON p.id=u.p" . $sc)->fetchAll(PDO::FETCH_ASSOC);
    $loss = 0;
    foreach ($rows as $r) $loss += (int)$r['rent'];
    return ['units' => $rows, 'count' => count($rows), 'monthly_loss' => $loss, 'annual_loss' => $loss * 12];
}
function analytics_forecast($pdo, $scope = '') {
    $t = analytics_trends($pdo, 6, $scope);
    $issued = array_sum(array_column($t['months'], 'issued'));
    $coll = array_sum(array_column($t['months'], 'collected'));
    $rate = $issued ? (int)round($coll / $issued * 100) : 0;
    $avgIssued = $issued ? (int)round($issued / count($t['months'])) : 0;
    $avgColl = (int)round($avgIssued * $rate / 100);
    $v = analytics_vacancy($pdo, $scope);
    $sc = $scope ? " AND u IN (SELECT id FROM units WHERE sub_email=" . $pdo->quote($scope) . ")" : '';
    $renewals = (int)$pdo->query("SELECT COUNT(*) FROM leases WHERE status='Active' AND end <= date('now','+60 days') AND end >= date('now')" . $sc)->fetchColumn();
    $months = [];
    $base = new DateTime(date('Y-m-01'));
    for ($i = 1; $i <= 12; $i++) {
        $m = (clone $base)->modify("+{$i} months")->format('Y-m');
        $months[] = ['month' => $m, 'expected' => $avgIssued, 'collected' => $avgColl];
    }
    $topRisk = $v['count'] ? $v['count'] . ' vacant unit(s) → ৳' . number_format($v['monthly_loss']) . '/mo lost' : ($renewals ? $renewals . ' lease renewal(s) due' : 'None — healthy');
    return [
        'collection_rate' => $rate, 'avg_issued' => $avgIssued, 'avg_collected' => $avgColl,
        'months' => $months, 'total_forecast' => $avgColl * 12, 'avg_month' => $avgColl,
        'occupancy' => $t['occupancy'], 'leased' => $t['leased'], 'units' => $t['units'],
        'vacancy_loss' => $v['monthly_loss'], 'vacant_units' => $v['count'],
        'renewals_due' => $renewals, 'top_risk' => $topRisk,
    ];
}
/* ---------- V2.0.2: analytics expansion — cashflow, collections, expenses, scores, occupancy, maintenance ---------- */
function analytics_cashflow($pdo, $months = 12, $scope = '') {
    $sc = $scope ? ' AND inv IN (SELECT i.id FROM invoices i JOIN leases l ON l.id=i.l JOIN units u ON u.id=l.u WHERE u.sub_email=' . $pdo->quote($scope) . ')' : '';
    $incSt = $pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM payments WHERE status='Success' AND substr(date,1,7)=?" . $sc);
    $mntSc = $scope ? " AND (unit IN (SELECT id FROM units WHERE sub_email=" . $pdo->quote($scope) . ") OR prop IN (SELECT id FROM properties WHERE sub_email=" . $pdo->quote($scope) . "))" : '';
    $mntSt = $pdo->prepare("SELECT COALESCE(SUM(actual_cost),0) FROM maintenance_requests WHERE pay_paid=1 AND substr(pay_paid_at,1,7)=?" . $mntSc);
    $vpSc = $scope ? " AND partner IN (SELECT id FROM partners WHERE sub_email=" . $pdo->quote($scope) . ")" : '';
    $vpSt  = $pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM vendor_payouts WHERE status='Paid' AND month=?" . $vpSc);
    $spSc = $scope ? " AND prop IN (SELECT id FROM properties WHERE sub_email=" . $pdo->quote($scope) . ")" : '';
    $spSt  = $pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM statement_payouts WHERE status='Paid' AND month=?" . $spSc);
    $out = []; $cum = 0; $cur = new DateTime(date('Y-m-01'));
    for ($i = $months - 1; $i >= 0; $i--) {
        $m = (clone $cur)->modify("-{$i} months")->format('Y-m');
        $incSt->execute([$m]); $income = (int)$incSt->fetchColumn();
        $mntSt->execute([$m]); $exp = (int)$mntSt->fetchColumn();
        $vpSt->execute([$m]);  $exp += (int)$vpSt->fetchColumn();
        $spSt->execute([$m]);  $exp += (int)$spSt->fetchColumn();
        $cum += $income - $exp;
        $out[] = ['month' => $m, 'income' => $income, 'expenses' => $exp, 'net' => $income - $exp, 'cumulative' => $cum];
    }
    $totI = array_sum(array_column($out, 'income')); $totE = array_sum(array_column($out, 'expenses'));
    return ['months' => $out, 'total_income' => $totI, 'total_expenses' => $totE, 'total_net' => $totI - $totE, 'expense_ratio' => $totI ? (int)round($totE / $totI * 100) : 0];
}
function analytics_collections($pdo, $months = 12, $scope = '') {
    $sc = $scope ? ' AND inv IN (SELECT i.id FROM invoices i JOIN leases l ON l.id=i.l JOIN units u ON u.id=l.u WHERE u.sub_email=' . $pdo->quote($scope) . ')' : '';
    $byMethod = $pdo->query("SELECT method, COUNT(*) n, SUM(amount) amount FROM payments WHERE status='Success'" . $sc . " GROUP BY method ORDER BY amount DESC")->fetchAll(PDO::FETCH_ASSOC);
    $onTime = 0; $late = 0; $lateDays = 0; $lateAmt = 0;
    foreach ($pdo->query("SELECT p.date pd, p.amount, i.m mth FROM payments p JOIN invoices i ON i.id=p.inv WHERE p.status='Success'" . $sc)->fetchAll(PDO::FETCH_ASSOC) as $r) {
        if (!$r['mth'] || !$r['pd']) continue;
        $due = strtotime($r['mth'] . '-01') + 3 * 86400;  // 1st + 3-day grace
        $pd = strtotime($r['pd']);
        if ($pd <= $due) { $onTime++; }
        else { $late++; $lateDays += max(0, (int)floor(($pd - $due) / 86400)); $lateAmt += (int)$r['amount']; }
    }
    $issSc = $scope ? ' AND l IN (SELECT l.id FROM leases l JOIN units u ON u.id=l.u WHERE u.sub_email=' . $pdo->quote($scope) . ')' : '';
    $issSt = $pdo->prepare('SELECT COALESCE(SUM(net),0) FROM invoices WHERE m=?' . $issSc);
    $colSt = $pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM payments p JOIN invoices i ON i.id=p.inv WHERE i.m=?" . $sc . " AND p.status='Success'");
    $byMonth = []; $cur = new DateTime(date('Y-m-01'));
    for ($i = $months - 1; $i >= 0; $i--) {
        $m = (clone $cur)->modify("-{$i} months")->format('Y-m');
        $issSt->execute([$m]); $iss = (int)$issSt->fetchColumn();
        $colSt->execute([$m]); $col = (int)$colSt->fetchColumn();
        $byMonth[] = ['month' => $m, 'issued' => $iss, 'collected' => $col, 'rate' => $iss ? (int)round($col / $iss * 100) : 0];
    }
    $tot = $onTime + $late;
    return ['by_method' => $byMethod, 'by_month' => $byMonth, 'payments' => $tot,
        'on_time' => $onTime, 'late' => $late, 'on_time_rate' => $tot ? (int)round($onTime / $tot * 100) : 0,
        'avg_days_late' => $late ? (int)round($lateDays / $late) : 0, 'late_amount' => $lateAmt];
}
function analytics_expenses($pdo, $months = 12, $scope = '') {
    $sc = $scope ? " AND (unit IN (SELECT id FROM units WHERE sub_email=" . $pdo->quote($scope) . ") OR prop IN (SELECT id FROM properties WHERE sub_email=" . $pdo->quote($scope) . "))" : '';
    $where = $sc ? ' WHERE 1=1' : '';
    $totalPaid = (int)$pdo->query("SELECT COALESCE(SUM(actual_cost),0) FROM maintenance_requests" . $where . " AND pay_paid=1" . $sc)->fetchColumn();
    $totalAll = (int)$pdo->query('SELECT COALESCE(SUM(actual_cost),0) FROM maintenance_requests' . $where . $sc)->fetchColumn();
    $estOpen = (int)$pdo->query("SELECT COALESCE(SUM(cost_estimate),0) FROM maintenance_requests" . $where . " AND status NOT IN ('Closed','Cancelled','Done')" . $sc)->fetchColumn();
    $openCount = (int)$pdo->query("SELECT COUNT(*) FROM maintenance_requests" . $where . " AND status NOT IN ('Closed','Cancelled','Done')" . $sc)->fetchColumn();
    $byCategory = $pdo->query("SELECT COALESCE(NULLIF(category,''),'other') category, COUNT(*) n, COALESCE(SUM(actual_cost),0) cost FROM maintenance_requests" . $where . $sc . " GROUP BY category ORDER BY cost DESC")->fetchAll(PDO::FETCH_ASSOC);
    $byVendor = $pdo->query("SELECT COALESCE(NULLIF(vendor,''),'Unassigned') vendor, COUNT(*) n, COALESCE(SUM(actual_cost),0) cost FROM maintenance_requests" . $where . " AND vendor<>''" . $sc . " GROUP BY vendor ORDER BY cost DESC LIMIT 12")->fetchAll(PDO::FETCH_ASSOC);
    $byProperty = $pdo->query("SELECT COALESCE(NULLIF(m.prop,''),'—') prop, COALESCE(p.name, COALESCE(NULLIF(m.prop,''),'—')) name, COUNT(*) n, COALESCE(SUM(m.actual_cost),0) cost, SUM(CASE WHEN m.status NOT IN ('Closed','Cancelled','Done') THEN 1 ELSE 0 END) open FROM maintenance_requests m LEFT JOIN properties p ON p.id=m.prop" . $where . $sc . " GROUP BY m.prop ORDER BY cost DESC")->fetchAll(PDO::FETCH_ASSOC);
    $trSt = $pdo->prepare("SELECT COALESCE(SUM(actual_cost),0) FROM maintenance_requests WHERE 1=1 AND pay_paid=1 AND substr(pay_paid_at,1,7)=?" . $sc);
    $trend = []; $cur = new DateTime(date('Y-m-01'));
    for ($i = $months - 1; $i >= 0; $i--) {
        $m = (clone $cur)->modify("-{$i} months")->format('Y-m');
        $trSt->execute([$m]); $trend[] = ['month' => $m, 'cost' => (int)$trSt->fetchColumn()];
    }
    $avgJob = 0;
    $nn = (int)$pdo->query('SELECT COUNT(*) FROM maintenance_requests' . $where . " AND actual_cost>0" . $sc)->fetchColumn();
    if ($nn) $avgJob = (int)round($totalAll / $nn);
    return ['total_paid' => $totalPaid, 'total_all' => $totalAll, 'estimated_open' => $estOpen, 'open_count' => $openCount,
        'avg_job_cost' => $avgJob, 'by_category' => $byCategory, 'by_vendor' => $byVendor, 'by_property' => $byProperty, 'trend' => $trend];
}
function analytics_scores($pdo, $scope = '') {
    $tenants = $pdo->query('SELECT DISTINCT t.id, t.name, t.kind FROM tenants t JOIN leases l ON l.t=t.id' . ($scope ? ' WHERE t.sub_email=' . $pdo->quote($scope) : ''))->fetchAll(PDO::FETCH_ASSOC);
    $bands = ['Excellent' => 0, 'Good' => 0, 'Fair' => 0, 'Risky' => 0];
    $atRisk = []; $scoreSum = 0; $scored = 0;
    foreach ($tenants as $t) {
        $sc = tenant_scorecard($pdo, $t['id']);
        if (!$sc) continue;
        $bands[$sc['band']] = ($bands[$sc['band']] ?? 0) + 1;
        $scoreSum += $sc['score']; $scored++;
        if ($sc['band'] === 'Risky' || $sc['band'] === 'Fair') {
            $atRisk[] = ['id' => $t['id'], 'name' => $t['name'], 'kind' => $t['kind'] ?? '', 'score' => $sc['score'],
                'band' => $sc['band'], 'band_color' => $sc['band_color'] ?? '', 'overdue' => $sc['stats']['overdue'] ?? 0,
                'on_time' => $sc['stats']['on_time_rate'] ?? 0, 'tenure' => $sc['stats']['tenure_months'] ?? 0,
                'tickets_open' => $sc['stats']['tickets_open'] ?? 0];
        }
    }
    usort($atRisk, fn($a, $b) => $a['score'] <=> $b['score']);
    return ['bands' => $bands, 'total' => $scored, 'avg_score' => $scored ? (int)round($scoreSum / $scored) : 0, 'at_risk' => $atRisk];
}
function analytics_occupancy($pdo, $scope = '') {
    $props = $pdo->query('SELECT id, name, type FROM properties' . ($scope ? ' WHERE sub_email=' . $pdo->quote($scope) : '') . ' ORDER BY id')->fetchAll(PDO::FETCH_ASSOC);
    $rows = []; $totU = 0; $totL = 0; $roll = 0; $vLoss = 0;
    foreach ($props as $p) {
        $uSc = $scope ? ' AND sub_email=' . $pdo->quote($scope) : '';
        $uSt = $pdo->prepare('SELECT COUNT(*) FROM units WHERE p=?' . $uSc); $uSt->execute([$p['id']]); $units = (int)$uSt->fetchColumn();
        $lSt = $pdo->prepare("SELECT COUNT(*) FROM units WHERE p=?" . $uSc . " AND status='Leased'"); $lSt->execute([$p['id']]); $leased = (int)$lSt->fetchColumn();
        $rSt = $pdo->prepare("SELECT COALESCE(SUM(rent),0) FROM units WHERE p=?" . $uSc . " AND status='Leased'"); $rSt->execute([$p['id']]); $rentRoll = (int)$rSt->fetchColumn();
        $vSt = $pdo->prepare("SELECT COALESCE(SUM(rent),0) FROM units WHERE p=?" . $uSc . " AND status='Vacant'"); $vSt->execute([$p['id']]); $vacLoss = (int)$vSt->fetchColumn();
        $rows[] = ['prop' => $p['id'], 'name' => $p['name'], 'type' => $p['type'], 'units' => $units, 'leased' => $leased,
            'vacant' => $units - $leased, 'occupancy' => $units ? (int)round($leased / $units * 100) : 0,
            'rent_roll' => $rentRoll, 'vacancy_loss' => $vacLoss];
        $totU += $units; $totL += $leased; $roll += $rentRoll; $vLoss += $vacLoss;
    }
    $sc = $scope ? " AND l.u IN (SELECT id FROM units WHERE sub_email=" . $pdo->quote($scope) . ")" : '';
    $exp = $pdo->query("SELECT l.id, l.end, l.rent, t.name tenant, u.name unit, p.name prop FROM leases l JOIN tenants t ON t.id=l.t JOIN units u ON u.id=l.u LEFT JOIN properties p ON p.id=u.p WHERE l.status='Active' AND l.end <= date('now','+90 days') AND l.end >= date('now')" . $sc . " ORDER BY l.end")->fetchAll(PDO::FETCH_ASSOC);
    return ['properties' => $rows, 'units' => $totU, 'leased' => $totL, 'vacant' => $totU - $totL,
        'occupancy' => $totU ? (int)round($totL / $totU * 100) : 0, 'rent_roll' => $roll, 'vacancy_loss' => $vLoss, 'expiries' => $exp];
}
function analytics_maintenance($pdo, $scope = '') {
    $sc = $scope ? " WHERE (unit IN (SELECT id FROM units WHERE sub_email=" . $pdo->quote($scope) . ") OR prop IN (SELECT id FROM properties WHERE sub_email=" . $pdo->quote($scope) . "))" : '';
    $byStatus = $pdo->query('SELECT status, COUNT(*) n FROM maintenance_requests' . $sc . ' GROUP BY status ORDER BY n DESC')->fetchAll(PDO::FETCH_ASSOC);
    $byPriority = $pdo->query('SELECT priority, COUNT(*) n FROM maintenance_requests' . $sc . ' GROUP BY priority ORDER BY n DESC')->fetchAll(PDO::FETCH_ASSOC);
    $byCharge = $pdo->query("SELECT charge_to, COUNT(*) n, COALESCE(SUM(actual_cost),0) cost FROM maintenance_requests" . $sc . " GROUP BY charge_to ORDER BY cost DESC")->fetchAll(PDO::FETCH_ASSOC);
    $byProperty = $pdo->query("SELECT COALESCE(NULLIF(m.prop,''),'—') prop, COALESCE(p.name, COALESCE(NULLIF(m.prop,''),'—')) name, COUNT(*) n, COALESCE(SUM(m.actual_cost),0) cost, SUM(CASE WHEN m.status NOT IN ('Closed','Cancelled','Done') THEN 1 ELSE 0 END) open FROM maintenance_requests m LEFT JOIN properties p ON p.id=m.prop" . $sc . " GROUP BY m.prop ORDER BY n DESC")->fetchAll(PDO::FETCH_ASSOC);
    $totalCost = (int)$pdo->query('SELECT COALESCE(SUM(actual_cost),0) FROM maintenance_requests' . $sc)->fetchColumn();
    $estOpen = (int)$pdo->query("SELECT COALESCE(SUM(cost_estimate),0) FROM maintenance_requests" . $sc . ($sc ? " AND status NOT IN ('Closed','Cancelled','Done')" : " WHERE status NOT IN ('Closed','Cancelled','Done')"))->fetchColumn();
    $openCount = (int)$pdo->query("SELECT COUNT(*) FROM maintenance_requests" . $sc . ($sc ? " AND status NOT IN ('Closed','Cancelled','Done')" : " WHERE status NOT IN ('Closed','Cancelled','Done')"))->fetchColumn();
    $doneCount = (int)$pdo->query("SELECT COUNT(*) FROM maintenance_requests" . $sc . ($sc ? " AND status IN ('Closed','Done')" : " WHERE status IN ('Closed','Done')"))->fetchColumn();
    $avgResolve = (float)$pdo->query("SELECT COALESCE(AVG(julianday(updated_at)-julianday(ts)),0) FROM maintenance_requests" . $sc . ($sc ? " AND status IN ('Closed','Done') AND updated_at<>ts AND updated_at<>''" : " WHERE status IN ('Closed','Done') AND updated_at<>ts AND updated_at<>''"))->fetchColumn();
    $aging = $pdo->query("SELECT id, title, status, priority, CAST(julianday('now')-julianday(ts) AS INTEGER) days FROM maintenance_requests" . $sc . ($sc ? " AND status NOT IN ('Closed','Cancelled','Done')" : " WHERE status NOT IN ('Closed','Cancelled','Done')") . " ORDER BY days DESC LIMIT 10")->fetchAll(PDO::FETCH_ASSOC);
    return ['by_status' => $byStatus, 'by_priority' => $byPriority, 'by_charge' => $byCharge, 'by_property' => $byProperty,
        'total_cost' => $totalCost, 'estimated_open' => $estOpen, 'open_count' => $openCount, 'done_count' => $doneCount,
        'avg_resolve_days' => round($avgResolve, 1), 'aging' => $aging];
}
/* V2.39.5: portfolio deadline calendar — leases ending, compliance expiries,
   open maintenance, pending renewals, unpaid invoices. Scoped exactly like the
   other analytics actions; used by the Analytics Overview calendar card. */
function analytics_calendar($pdo, $scope = '') {
    $events = [];
    $leaseSc = $scope ? " AND u.sub_email=" . $pdo->quote($scope) : '';
    $allSc  = $scope ? " AND (COALESCE(u.sub_email,'')=" . $pdo->quote($scope)
        . " OR COALESCE(p.sub_email,'')=" . $pdo->quote($scope)
        . " OR COALESCE(t.sub_email,'')=" . $pdo->quote($scope) . ")" : '';
    $maintSc = $scope ? " AND (COALESCE(u.sub_email,'')=" . $pdo->quote($scope)
        . " OR COALESCE(p.sub_email,'')=" . $pdo->quote($scope) . ")" : '';
    /* lease endings (next 120 days, active leases) */
    $ls = $pdo->query("SELECT l.id, l.u, l.t, l.end, u.name AS unit, p.name AS prop, t.name AS tenant, t.phone AS tphone
        FROM leases l LEFT JOIN units u ON u.id=l.u LEFT JOIN properties p ON p.id=u.p LEFT JOIN tenants t ON t.id=l.t
        WHERE l.status IN ('Active','active') AND l.end<>'' AND l.end>=date('now')
        AND l.end<=date('now','+120 days')" . $leaseSc . " ORDER BY l.end")->fetchAll(PDO::FETCH_ASSOC);
    foreach ($ls as $r) {
        $events[] = ['date' => $r['end'], 'kind' => 'lease', 'title' => 'Lease ends · ' . ($r['unit'] ?: $r['id']),
            'sub' => ($r['tenant'] ?: '') . ($r['unit'] ? ' · ' . $r['unit'] : '') . ($r['prop'] ? ' · ' . $r['prop'] : ''),
            'days' => (int)ceil((strtotime($r['end']) - time()) / 86400), 'ref' => $r['id']];
    }
    /* compliance expiries (next 120 days, not resolved) */
    $cs = $pdo->query("SELECT c.*, p.name AS prop, u.name AS unit, t.name AS tenant FROM compliance_items c
        LEFT JOIN properties p ON p.id=c.entity_id LEFT JOIN units u ON u.id=c.entity_id LEFT JOIN tenants t ON t.id=c.entity_id
        WHERE c.expiry_date<>'' AND c.expiry_date>=date('now') AND c.expiry_date<=date('now','+120 days')
        AND c.status NOT IN ('Resolved','Closed','Done')" . $allSc . " ORDER BY c.expiry_date")->fetchAll(PDO::FETCH_ASSOC);
    foreach ($cs as $r) {
        $events[] = ['date' => $r['expiry_date'], 'kind' => 'compliance', 'title' => $r['label'],
            'sub' => ($r['item'] ?: '') . (($r['prop'] ?: $r['unit'] ?: $r['tenant']) ? ' · ' . ($r['prop'] ?: $r['unit'] ?: $r['tenant']) : ''),
            'days' => (int)ceil((strtotime($r['expiry_date']) - time()) / 86400), 'ref' => $r['id']];
    }
    /* open maintenance (aging in days) */
    $ms = $pdo->query("SELECT m.id, m.title, m.status, m.priority, m.ts, u.name AS unit, p.name AS prop, m.cost_estimate
        FROM maintenance_requests m LEFT JOIN units u ON u.id=m.unit LEFT JOIN properties p ON p.id=m.prop
        WHERE m.status NOT IN ('Closed','Cancelled','Done')" . $maintSc . " ORDER BY m.ts LIMIT 15")->fetchAll(PDO::FETCH_ASSOC);
    foreach ($ms as $r) {
        $days = (int)floor((time() - strtotime($r['ts'])) / 86400);
        $events[] = ['date' => substr((string)$r['ts'], 0, 10), 'kind' => 'maintenance', 'title' => '🛠 ' . $r['title'],
            'sub' => ($r['unit'] ?: $r['prop'] ?: '') . ' · ' . $r['status'] . ($days > 0 ? ' · ' . $days . 'd open' : ''),
            'days' => $days, 'ref' => $r['id']];
    }
    /* pending renewals */
    $rs = $pdo->query("SELECT r.id, r.lease, r.months, r.new_rent, r.status, l.end, u.name AS unit, t.name AS tenant
        FROM renewal_requests r LEFT JOIN leases l ON l.id=r.lease LEFT JOIN units u ON u.id=l.u LEFT JOIN tenants t ON t.id=l.t
        WHERE r.status IN ('Pending','pending','Approved','approved')" . $leaseSc . " ORDER BY r.ts")->fetchAll(PDO::FETCH_ASSOC);
    foreach ($rs as $r) {
        $events[] = ['date' => $r['end'] ?: substr((string)$r['ts'], 0, 10), 'kind' => 'renewal', 'title' => 'Renewal · ' . ($r['tenant'] ?: ''),
            'sub' => ($r['unit'] ?: '') . ' · ' . $r['status'] . ($r['months'] ? ' · +' . $r['months'] . 'mo' : '') . ($r['new_rent'] ? ' · ৳' . number_format((float)$r['new_rent']) : ''),
            'days' => $r['end'] ? (int)ceil((strtotime($r['end']) - time()) / 86400) : 0, 'ref' => $r['id']];
    }
    /* unpaid invoices (current + past month) */
    $invSc = $scope ? " AND l.id IN (SELECT l2.id FROM leases l2 JOIN units u2 ON u2.id=l2.u WHERE u2.sub_email=" . $pdo->quote($scope) . ")" : '';
    $is = $pdo->query("SELECT i.id, i.m, i.net, i.status, l.u, u.name AS unit, t.name AS tenant
        FROM invoices i LEFT JOIN leases l ON l.id=i.l LEFT JOIN units u ON u.id=l.u LEFT JOIN tenants t ON t.id=l.t
        WHERE i.status NOT IN ('Paid','Waived','Cancelled') AND i.m>=date('now','-1 month','start of month')" . $invSc . " ORDER BY i.m")->fetchAll(PDO::FETCH_ASSOC);
    foreach ($is as $r) {
        $events[] = ['date' => $r['m'] . '-01', 'kind' => 'invoice', 'title' => 'Invoice ' . $r['m'] . ' · ' . ($r['tenant'] ?: ''),
            'sub' => ($r['unit'] ?: '') . ' · ' . $r['status'] . ' · ৳' . number_format((float)$r['net']),
            'days' => 0, 'ref' => $r['id']];
    }
    usort($events, fn($a, $b) => strcmp($a['date'], $b['date']));
    $byKind = [];
    foreach ($events as $e) $byKind[$e['kind']] = ($byKind[$e['kind']] ?? 0) + 1;
    return ['events' => $events, 'by_kind' => $byKind, 'month' => date('Y-m')];
}
function board_report_md($pdo, $month, $scope = '') {
    $pnl = analytics_pnl($pdo, $month, $scope);
    $tr = analytics_trends($pdo, 6, $scope);
    $ag = analytics_aging($pdo, $scope);
    $vc = analytics_vacancy($pdo, $scope);
    $fc = analytics_forecast($pdo, $scope);
    $cf = analytics_cashflow($pdo, 12, $scope);
    $co = analytics_collections($pdo, 12, $scope);
    $oc = analytics_occupancy($pdo, $scope);
    $mt = analytics_maintenance($pdo, $scope);
    $sc = analytics_scores($pdo, $scope);
    $t = $pnl['totals'];
    $l = [];
    $l[] = '# KRTaker Portfolio Board Report — ' . $month;
    $l[] = '';
    $l[] = '## Executive summary';
    $l[] = '';
    $l[] = '- Gross rent: ৳' . number_format($t['gross']) . ' · Collected: ৳' . number_format($t['collected']) . ' · Net: ৳' . number_format($t['net']);
    $l[] = '- Collection rate: ' . ($fc['collection_rate'] ?? $co['on_time_rate']) . '% · On-time payments: ' . $co['on_time_rate'] . '% (' . $co['on_time'] . '/' . ($co['payments'] ?: 0) . ')';
    $l[] = '- Occupancy: ' . $oc['occupancy'] . '% (' . $oc['leased'] . '/' . $oc['units'] . ' units) · Arrears: ৳' . number_format($ag['total']);
    $l[] = '- Vacancy loss: ৳' . number_format($vc['monthly_loss']) . '/mo · 12-mo net flow: ৳' . number_format($cf['total_net']);
    $l[] = '- Top risk: ' . $fc['top_risk'];
    $l[] = '';
    $l[] = '## P&L (' . $month . ')';
    $l[] = '';
    $l[] = '| Property | Gross | Collected | TDS | Service | Expenses | Net |';
    $l[] = '|---|---|---|---|---|---|---|';
    foreach ($pnl['properties'] as $r) $l[] = '| ' . $r['name'] . ' | ৳' . number_format($r['gross']) . ' | ৳' . number_format($r['collected']) . ' | ৳' . number_format($r['tds']) . ' | ৳' . number_format($r['service']) . ' | ৳' . number_format($r['expenses']) . ' | ৳' . number_format($r['net']) . ' |';
    $l[] = '| **Total** | **৳' . number_format($t['gross']) . '** | **৳' . number_format($t['collected']) . '** | **৳' . number_format($t['tds']) . '** | **৳' . number_format($t['service']) . '** | **৳' . number_format($t['expenses']) . '** | **৳' . number_format($t['net']) . '** |';
    $l[] = '';
    $l[] = '## Cashflow · 12 months';
    $l[] = '';
