        if ($nOrg !== $myOrg && $nOrg !== '')
            json_out(['ok' => false, 'error' => 'You can only delete notices from your own workspace.'], 403);
    }
    $pdo->prepare('DELETE FROM notices WHERE id=?')->execute([$id]);
    audit($u['name'], 'Notice deleted', 'notices', $id);
