case 'app-ai-chat': {
    $u = require_user();
    require_module($u, 'ai');
    $messages = $body['messages'] ?? [];
    if (!is_array($messages) || !$messages) json_out(['ok' => false, 'error' => 'messages required.'], 400);
    $last = end($messages);
    $q = is_array($last) ? trim($last['content'] ?? '') : '';
    if (!$q) json_out(['ok' => false, 'error' => 'Empty message.'], 400);
    $pdo = db();
    $_t0 = microtime(true);
    $mode = ai_mode($pdo);

    if ($mode === 'llm') {
        $msgs = array_merge([['role' => 'system', 'content' => ai_system_prompt($u)]], array_slice($messages, -12));
        $actions = [];
        $reply = '';
        try {
            $msg = ai_llm_call($msgs, $pdo);
            for ($i = 0; $i < 3; $i++) {
                if (isset($msg['error'])) { $reply = 'KR is having trouble reaching the model: ' . $msg['error']; break; }
                if (!empty($msg['tool_calls'])) {
                    $msgs[] = $msg;
                    foreach ($msg['tool_calls'] as $tc) {
                        $name = $tc['function']['name'] ?? '';
                        $args = json_decode($tc['function']['arguments'] ?? '{}', true) ?: [];
                        $res = ai_execute_tool($u, $name, $args);
                        $actions[] = ['tool' => $name, 'ok' => $res['ok']];
                        $msgs[] = ['role' => 'tool', 'tool_call_id' => $tc['id'] ?? '', 'content' => $res['text']];
                        if ($res['ok'] && isset($res['data'])) $actions[] = ['tool' => $name, 'ok' => true, 'data' => $res['data']];
                    }
                    $msg = ai_llm_call($msgs, $pdo);
                    continue;
                }
                $reply = $msg['content'] ?? 'No response.';
                break;
            }
            if (!$reply) $reply = 'I could not complete that. Please try again.';
        } catch (Exception $e) {
            $reply = 'KR error: ' . $e->getMessage();
        }
        $log_r = substr($reply, 0, 300);
    } else {
        $r = ai_offline($u, $q);
        $reply = $r['reply'];
        $actions = $r['actions'];
        $log_r = substr($reply, 0, 300);
        $mode = 'offline';
    }
    $pdo->prepare('INSERT INTO ai_log (user, mode, query, tool, result, ms) VALUES (?,?,?,?,?,?)')
        ->execute([$u['name'], $mode, substr($q, 0, 200), $actions[0]['tool'] ?? '', $log_r, (int)round((microtime(true) - $_t0) * 1000)]);
    json_out(['ok' => true, 'reply' => $reply, 'mode' => $mode, 'actions' => $actions]);
}

/* ── Mall / Commercial Property edition (feat/mall-management) ──
   Spec: mall_management_software_spec-1.docx — Mall Owners' Committee.
   Phase 1: shops master (generic CRUD), service-charge billing, elec/water
   sub-meter billing (custodial), collections, central ledger, dashboard. ── */
case 'mall': {
    $u = require_user();
    $pdo = db();
    $a = $body['action'] ?? '';
    $mall_roles = ['superadmin', 'owner', 'manager', 'accountant'];
    $mall_roles_read = array_merge($mall_roles, ['collector']);
    if (!in_array($u['role'], $mall_roles_read, true)) {
        json_out(['ok' => false, 'error' => 'Access denied — Mall module requires owner/manager/accountant/collector role.'], 403);
    }
    /* collector = field staff: may VIEW everything + record collections + enter
       meter readings. All other writes require owner/manager/accountant. */
    $is_collector = $u['role'] === 'collector';
    $mall_write = ['config-set', 'bill-generate', 'fine-calc', 'shop-create', 'shop-update', 'shop-delete',
                   'expense-add', 'expense-del', 'complaint-add', 'complaint-status', 'complaint-del',
                   'asset-add', 'asset-update', 'asset-del', 'notice-add', 'notice-del', 'notice-pin'];
    $collector_ok = ['collect', 'meter', 'readings'];
    if ($is_collector) {
        if (in_array($a, $mall_write, true)) {
            json_out(['ok' => false, 'error' => 'Collector role is limited to collections, meter readings and viewing.'], 403);
        }
        if (!in_array($a, $collector_ok, true) && !in_array($a, ['config-get', 'bills', 'payments', 'dashboard', 'ledger', 'expenses', 'complaints', 'assets', 'audit', 'notices', 'shop-list'], true)) {
            json_out(['ok' => false, 'error' => 'Unknown action for collector.'], 403);
        }
    }
    $mcfg = function ($k, $def = '') use ($pdo) {
        $st = $pdo->prepare('SELECT v FROM mall_config WHERE k=?'); $st->execute([$k]);
        $v = (string)$st->fetchColumn();
        return $v === '' ? $def : $v;
    };
    $mset = function ($k, $v) use ($pdo) {
        $pdo->prepare('INSERT INTO mall_config (k, v) VALUES (?,?) ON CONFLICT(k) DO UPDATE SET v=excluded.v')->execute([$k, (string)$v]);
    };

    /* config-get / config-set — mall-wide identity, rates, rules & receipt details */
    if ($a === 'config-get') {
        json_out(['ok' => true, 'config' => [
            'mall_name'      => $mcfg('mall_name', ''),
            'mall_address'   => $mcfg('mall_address', ''),
            'mall_phone'     => $mcfg('mall_phone', ''),
            'mall_email'     => $mcfg('mall_email', ''),
            'chairman'       => $mcfg('chairman', ''),
            'secretary'      => $mcfg('secretary', ''),
            'elec_unit_rate' => (int)$mcfg('elec_unit_rate', '8'),
            'water_unit_rate'=> (int)$mcfg('water_unit_rate', '30'),
            'late_fee_pct'   => (int)$mcfg('late_fee_pct', '5'),
            'due_day'        => (int)$mcfg('due_day', '10'),
            'bank_name'      => $mcfg('bank_name', ''),
            'bank_account_title' => $mcfg('bank_account_title', ''),
            'bank_account_no'    => $mcfg('bank_account_no', ''),
            'receipt_note'   => $mcfg('receipt_note', ''),
        ]]);
    }
    if ($a === 'config-set') {
        foreach (['mall_name', 'mall_address', 'mall_phone', 'mall_email', 'chairman', 'secretary',
                  'elec_unit_rate', 'water_unit_rate', 'late_fee_pct', 'due_day',
                  'bank_name', 'bank_account_title', 'bank_account_no', 'receipt_note'] as $ck) {
            if (isset($body[$ck])) $mset($ck, $body[$ck]);
        }
        audit($u['name'], 'Mall config', 'mall', '', json_encode($body));
        json_out(['ok' => true]);
    }

    /* fine-calc — spec 3.2: late payment fine auto-calculation. For every unpaid
       bill in a month past its due date: fine = amount * late_fee_pct / 100. */
    if ($a === 'fine-calc') {
        $month = trim($body['month'] ?? date('Y-m'));
        $pct = (int)$mcfg('late_fee_pct', '5');
        $st = $pdo->prepare("SELECT id, amount FROM shop_bills WHERE month=? AND status='Unpaid' AND due_date != '' AND due_date < date('now')");
        $st->execute([$month]);
        $rows = $st->fetchAll(PDO::FETCH_ASSOC);
        $n = 0; $total = 0;
        $upd = $pdo->prepare("UPDATE shop_bills SET fine=? WHERE id=?");
        foreach ($rows as $r) {
            $fine = (int)round((int)$r['amount'] * $pct / 100);
            $upd->execute([$fine, $r['id']]);
            $n++; $total += $fine;
        }
        audit($u['name'], 'Fine calc', 'mall', $month, "$n bills, ৳$total");
        json_out(['ok' => true, 'count' => $n, 'total_fine' => $total, 'pct' => $pct]);
    }

    /* receipt — full receipt payload (bill + shop + payment) for printing. */
    if ($a === 'receipt') {
        $billId = (int)($body['bill_id'] ?? 0);
        if (!$billId) json_out(['ok' => false, 'error' => 'bill_id required.'], 400);
        $st = $pdo->prepare("SELECT b.*, s.no AS shop_no, s.floor AS shop_floor, s.owner_name, s.owner_mobile
                             FROM shop_bills b LEFT JOIN shops s ON s.id=b.shop WHERE b.id=?");
        $st->execute([$billId]);
        $bill = $st->fetch(PDO::FETCH_ASSOC);
        if (!$bill) json_out(['ok' => false, 'error' => 'Bill not found.'], 404);
        $pay = null;
        $ps = $pdo->prepare("SELECT * FROM shop_payments WHERE bill_id=? ORDER BY id DESC LIMIT 1");
        $ps->execute([$billId]);
        $pay = $ps->fetch(PDO::FETCH_ASSOC) ?: null;
        json_out(['ok' => true, 'bill' => $bill, 'payment' => $pay,
                  'mall_name' => $mcfg('mall_name', '')]);
    }

    /* readings — list sub-meter readings for a month (with shop numbers) */
    if ($a === 'readings') {
        $month = trim($body['month'] ?? date('Y-m'));
        $st = $pdo->prepare("SELECT r.*, s.no FROM mall_meter_readings r LEFT JOIN shops s ON s.id=r.shop
                             WHERE r.month=? ORDER BY r.id DESC LIMIT 100");
        $st->execute([$month]);
        json_out(['ok' => true, 'readings' => $st->fetchAll(PDO::FETCH_ASSOC)]);
    }

    /* expenses — list month expenses from company_ledger (kind=expense, cat=mall category) */
    if ($a === 'expenses' || $a === 'expense-add' || $a === 'expense-del') {
        /* fresh-DB guard: company_ledger may lack note/payee (added later on prod) */
        $lcols = array_column($pdo->query('PRAGMA table_info(company_ledger)')->fetchAll(PDO::FETCH_ASSOC), 'name');
        foreach (['note', 'payee'] as $lc) {
            if (!in_array($lc, $lcols, true)) { try { $pdo->exec("ALTER TABLE company_ledger ADD COLUMN $lc TEXT DEFAULT ''"); } catch (Exception $e) {} }
        }
    }
    if ($a === 'expenses') {
        $month = trim($body['month'] ?? date('Y-m'));
        $st = $pdo->prepare("SELECT id, cat AS category, amount, method, payee AS vendor, note, ts AS date
                             FROM company_ledger WHERE kind='expense' AND substr(ts,1,7)=? ORDER BY id DESC");
        $st->execute([$month]);
        $rows = $st->fetchAll(PDO::FETCH_ASSOC);
        $total = array_sum(array_map(fn($r) => (int)$r['amount'], $rows));
        json_out(['ok' => true, 'expenses' => $rows, 'total' => $total]);
    }

    /* expense-add — record a mall expense (lift/escalator/elec/AC/generator/cleaning/security/salary) */
    if ($a === 'expense-add') {
        $cat = trim($body['category'] ?? '');
        $amount = (int)($body['amount'] ?? 0);
        if ($cat === '' || $amount <= 0) json_out(['ok' => false, 'error' => 'category and amount required.'], 400);
        $method = in_array(trim($body['method'] ?? ''), ['cash', 'bank', 'bkash', 'nagad'], true) ? trim($body['method']) : 'cash';
        $pdo->prepare("INSERT INTO company_ledger (kind, cat, label, amount, method, ref, note, payee, ts)
                       VALUES ('expense', ?, ?, ?, ?, ?, ?, ?, datetime('now'))")
            ->execute([$cat, $cat . ' — ' . trim($body['note'] ?? ''), $amount, $method, '', trim($body['note'] ?? ''), trim($body['vendor'] ?? '')]);
        audit($u['name'], 'Expense', 'mall', $cat, "$amount via $method");
        json_out(['ok' => true]);
    }

    /* expense-del — remove a mistaken expense entry */
    if ($a === 'expense-del') {
        $id = (int)($body['id'] ?? 0);
        if (!$id) json_out(['ok' => false, 'error' => 'id required.'], 400);
        $pdo->prepare("DELETE FROM company_ledger WHERE id=? AND kind='expense'")->execute([$id]);
        audit($u['name'], 'Expense delete', 'mall', (string)$id, '');
        json_out(['ok' => true]);
    }

    /* payments — collection history for the month (receipts ledger) */
    if ($a === 'payments') {
        $month = trim($body['month'] ?? date('Y-m'));
        $st = $pdo->prepare("SELECT p.*, s.no AS shop_no, s.floor AS shop_floor
                             FROM shop_payments p LEFT JOIN shops s ON s.id=p.shop
                             WHERE p.month=? ORDER BY p.id DESC");
        $st->execute([$month]);
        json_out(['ok' => true, 'payments' => $st->fetchAll(PDO::FETCH_ASSOC)]);
    }

    /* complaints — list with shop info; filters: status, priority */
    if ($a === 'complaints') {
        $status = trim($body['status'] ?? '');
        $sql = "SELECT c.*, s.no AS shop_no, s.floor AS shop_floor, s.owner_name, s.owner_mobile
                FROM mall_complaints c LEFT JOIN shops s ON s.id=c.shop";
        $args = [];
        if ($status !== '') { $sql .= ' WHERE c.status=?'; $args[] = $status; }
        $sql .= ' ORDER BY c.id DESC LIMIT 200';
        $st = $pdo->prepare($sql); $st->execute($args);
        $rows = $st->fetchAll(PDO::FETCH_ASSOC);
        $counts = ['Open' => 0, 'In Progress' => 0, 'Resolved' => 0];
        foreach ($rows as $r) if (isset($counts[$r['status']])) $counts[$r['status']]++;
        json_out(['ok' => true, 'complaints' => $rows, 'counts' => $counts]);
    }
    if ($a === 'complaint-add') {
        $shop = trim($body['shop'] ?? '');
        $subject = trim($body['subject'] ?? '');
        if (!$shop || $subject === '') json_out(['ok' => false, 'error' => 'shop and subject required.'], 400);
        $pdo->prepare("INSERT INTO mall_complaints (shop, subject, descr, priority, status, note, created_by)
                       VALUES (?,?,?,?, 'Open', ?, ?)")
            ->execute([$shop, $subject, trim($body['descr'] ?? ''), in_array(trim($body['priority'] ?? ''), ['Low', 'Normal', 'High', 'Urgent'], true) ? trim($body['priority']) : 'Normal', trim($body['note'] ?? ''), $u['name']]);
        audit($u['name'], 'Complaint', 'mall', $shop, $subject);
        json_out(['ok' => true]);
    }
    if ($a === 'complaint-status') {
        $id = (int)($body['id'] ?? 0);
        $status = trim($body['status'] ?? '');
        if (!$id || !in_array($status, ['Open', 'In Progress', 'Resolved'], true)) json_out(['ok' => false, 'error' => 'id and status (Open/In Progress/Resolved) required.'], 400);
        $pdo->prepare("UPDATE mall_complaints SET status=?, resolved_at=CASE WHEN ?='Resolved' THEN datetime('now') ELSE '' END, note=? WHERE id=?")
            ->execute([$status, $status, trim($body['note'] ?? ''), $id]);
        audit($u['name'], 'Complaint status', 'mall', (string)$id, $status);
        json_out(['ok' => true]);
    }
    if ($a === 'complaint-del') {
        $id = (int)($body['id'] ?? 0);
        if (!$id) json_out(['ok' => false, 'error' => 'id required.'], 400);
        $pdo->prepare('DELETE FROM mall_complaints WHERE id=?')->execute([$id]);
        audit($u['name'], 'Complaint delete', 'mall', (string)$id, '');
        json_out(['ok' => true]);
    }

    /* assets — list + AMC/warranty reminders (contract expiring within 30 days) */
    if ($a === 'assets') {
        $rows = $pdo->query('SELECT * FROM mall_assets ORDER BY id DESC LIMIT 200')->fetchAll(PDO::FETCH_ASSOC);
        $due = $pdo->query("SELECT * FROM mall_assets WHERE status='Active' AND contract_until != ''
                            AND contract_until <= date('now','+30 days') ORDER BY contract_until LIMIT 50")->fetchAll(PDO::FETCH_ASSOC);
        foreach ($rows as $i => $r) {
            $days = null;
            if ($r['contract_until'] !== '') $days = (int)round((strtotime($r['contract_until']) - time()) / 86400);
            $rows[$i]['days_left'] = $days;
        }
        json_out(['ok' => true, 'assets' => $rows, 'reminders' => $due]);
    }
    if ($a === 'asset-add') {
        $name = trim($body['name'] ?? '');
        if ($name === '') json_out(['ok' => false, 'error' => 'name required.'], 400);
        $pdo->prepare("INSERT INTO mall_assets (name, type, location, vendor, install_date, warranty_until, contract_until, cost, status, note)
                       VALUES (?,?,?,?,?,?,?,?,?,?)")
            ->execute([$name, trim($body['type'] ?? 'Lift'), trim($body['location'] ?? ''), trim($body['vendor'] ?? ''),
                       trim($body['install_date'] ?? ''), trim($body['warranty_until'] ?? ''), trim($body['contract_until'] ?? ''),
                       (int)($body['cost'] ?? 0), in_array(trim($body['status'] ?? ''), ['Active', 'Under Service', 'Out of Service'], true) ? trim($body['status']) : 'Active',
                       trim($body['note'] ?? '')]);
        audit($u['name'], 'Asset', 'mall', $name, 'added');
        json_out(['ok' => true]);
    }
    if ($a === 'asset-update') {
        $id = (int)($body['id'] ?? 0);
        if (!$id) json_out(['ok' => false, 'error' => 'id required.'], 400);
        $pdo->prepare("UPDATE mall_assets SET name=?, type=?, location=?, vendor=?, install_date=?, warranty_until=?, contract_until=?, cost=?, status=?, note=? WHERE id=?")
            ->execute([trim($body['name'] ?? ''), trim($body['type'] ?? ''), trim($body['location'] ?? ''), trim($body['vendor'] ?? ''),
                       trim($body['install_date'] ?? ''), trim($body['warranty_until'] ?? ''), trim($body['contract_until'] ?? ''),
                       (int)($body['cost'] ?? 0), trim($body['status'] ?? ''), trim($body['note'] ?? ''), $id]);
        audit($u['name'], 'Asset update', 'mall', (string)$id, '');
        json_out(['ok' => true]);
    }
    if ($a === 'asset-del') {
        $id = (int)($body['id'] ?? 0);
        if (!$id) json_out(['ok' => false, 'error' => 'id required.'], 400);
        $pdo->prepare('DELETE FROM mall_assets WHERE id=?')->execute([$id]);
        audit($u['name'], 'Asset delete', 'mall', (string)$id, '');
        json_out(['ok' => true]);
    }

    /* audit — committee activity trail (who did what, when) */
    if ($a === 'audit') {
        $q = trim($body['q'] ?? '');
        $sql = 'SELECT * FROM audit_log';
        $args = [];
        if ($q !== '') { $sql .= ' WHERE user LIKE ? OR action LIKE ? OR module LIKE ? OR entity LIKE ? OR details LIKE ?'; $like = '%' . $q . '%'; $args = [$like, $like, $like, $like, $like]; }
        $sql .= ' ORDER BY id DESC LIMIT 150';
        $st = $pdo->prepare($sql); $st->execute($args);
        json_out(['ok' => true, 'audit' => $st->fetchAll(PDO::FETCH_ASSOC)]);
    }

    /* notices — committee notice board (spec 3.9) */
    if ($a === 'notices') {
        $rows = $pdo->query('SELECT * FROM mall_notices ORDER BY pinned DESC, id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC);
        json_out(['ok' => true, 'notices' => $rows]);
    }
    if ($a === 'notice-add') {
        $title = trim($body['title'] ?? '');
        if ($title === '') json_out(['ok' => false, 'error' => 'title required.'], 400);
        $pdo->prepare("INSERT INTO mall_notices (title, body, date, pinned, author) VALUES (?,?,?,?,?)")
            ->execute([$title, trim($body['body'] ?? ''), trim($body['date'] ?? date('Y-m-d')), (int)($body['pinned'] ?? 0) ? 1 : 0, $u['name']]);
        audit($u['name'], 'Notice', 'mall', $title, 'posted');
        json_out(['ok' => true]);
    }
    if ($a === 'notice-del') {
        $id = (int)($body['id'] ?? 0);
        if (!$id) json_out(['ok' => false, 'error' => 'id required.'], 400);
        $pdo->prepare('DELETE FROM mall_notices WHERE id=?')->execute([$id]);
        audit($u['name'], 'Notice delete', 'mall', (string)$id, '');
        json_out(['ok' => true]);
    }
    if ($a === 'notice-pin') {
        $id = (int)($body['id'] ?? 0);
        if (!$id) json_out(['ok' => false, 'error' => 'id required.'], 400);
        $pdo->prepare('UPDATE mall_notices SET pinned=? WHERE id=?')->execute([(int)($body['pinned'] ?? 0) ? 1 : 0, $id]);
        json_out(['ok' => true]);
    }

    /* bills — list with shop info; filters: month (YYYY-MM), kind, status */
    if ($a === 'bills') {
        $month = trim($body['month'] ?? date('Y-m'));
        $kind  = trim($body['kind'] ?? '');
        $status = trim($body['status'] ?? '');
        $sql = "SELECT b.*, s.no AS shop_no, s.floor AS shop_floor, s.owner_name, s.owner_mobile
                FROM shop_bills b LEFT JOIN shops s ON s.id = b.shop WHERE b.month=?";
        $args = [$month];
        if ($kind !== '')   { $sql .= ' AND b.kind=?';  $args[] = $kind; }
        if ($status !== '') { $sql .= ' AND b.status=?'; $args[] = $status; }
        $sql .= ' ORDER BY s.floor, s.no';
        $st = $pdo->prepare($sql); $st->execute($args);
        $bills = $st->fetchAll(PDO::FETCH_ASSOC);
        $sum = $pdo->prepare("SELECT COALESCE(SUM(amount),0) billed, COALESCE(SUM(fine),0) fines,
                    COALESCE(SUM(CASE WHEN status='Paid' THEN amount ELSE 0 END),0) collected
                    FROM shop_bills WHERE month=?"); $sum->execute([$month]);
        json_out(['ok' => true, 'bills' => $bills, 'totals' => $sum->fetch(PDO::FETCH_ASSOC)]);
    }

    /* bill-generate — idempotent monthly service-charge bills for Active shops.
       Rate: shop.service_rate (flat, BDT) if set, else sqft * default-per-sqft (flat fallback). */
    if ($a === 'bill-generate') {
        $month = trim($body['month'] ?? date('Y-m'));
        $dueDay = (int)$mcfg('due_day', '10');
        $dueDate = date('Y-m-d', strtotime($month . '-' . sprintf('%02d', $dueDay)));
        $st = $pdo->prepare("SELECT id, service_rate, sqft FROM shops WHERE status='Active'");
        $st->execute();
        $shops = $st->fetchAll(PDO::FETCH_ASSOC);
        $created = 0; $skipped = 0;
        $exists = $pdo->prepare("SELECT COUNT(*) FROM shop_bills WHERE shop=? AND month=? AND kind='service'");
        $ins = $pdo->prepare("INSERT INTO shop_bills (shop, month, kind, amount, fine, due_date, status)
                              VALUES (?,?, 'service', ?, 0, ?, 'Unpaid')");
        foreach ($shops as $s) {
            $exists->execute([$s['id'], $month]);
            if ((int)$exists->fetchColumn() > 0) { $skipped++; continue; }
            $rate = (int)$s['service_rate'];
            if ($rate <= 0) $rate = max(0, (int)$s['sqft']) * (int)$mcfg('per_sqft_rate', '0');
            if ($rate <= 0) $rate = (int)$mcfg('service_default_rate', '500');
            $ins->execute([$s['id'], $month, $rate]);
            $created++;
        }
        audit($u['name'], 'Bill generate', 'mall', $month, "$created created, $skipped skipped");
        json_out(['ok' => true, 'created' => $created, 'skipped' => $skipped]);
    }

    /* collect — record a payment against a bill; marks bill Paid; receipt auto-numbered. */
    if ($a === 'collect') {
        $billId = (int)($body['bill_id'] ?? 0);
        if (!$billId) json_out(['ok' => false, 'error' => 'bill_id required.'], 400);
        $amount = (int)($body['amount'] ?? 0);
        if ($amount <= 0) json_out(['ok' => false, 'error' => 'amount required.'], 400);
        $method = trim($body['method'] ?? 'cash');
        if (!in_array($method, ['cash', 'bank', 'bkash', 'nagad'], true)) json_out(['ok' => false, 'error' => 'method must be cash/bank/bkash/nagad.'], 400);
        $st = $pdo->prepare("SELECT * FROM shop_bills WHERE id=?"); $st->execute([$billId]);
        $bill = $st->fetch(PDO::FETCH_ASSOC);
        if (!$bill) json_out(['ok' => false, 'error' => 'Bill not found.'], 404);
        if ($bill['status'] === 'Paid') json_out(['ok' => false, 'error' => 'Bill already paid.'], 409);
        $receipt = 'RCT-' . str_replace('-', '', $bill['month']) . '-' . str_pad((string)$billId, 4, '0', STR_PAD_LEFT);
        $pdo->prepare("INSERT INTO shop_payments (shop, bill_id, month, kind, amount, method, ref, receipt)
                       VALUES (?,?,?,?,?,?,?,?)")
            ->execute([$bill['shop'], $billId, $bill['month'], $bill['kind'], $amount, $method, trim($body['ref'] ?? ''), $receipt]);
        $pdo->prepare("UPDATE shop_bills SET status='Paid' WHERE id=?")->execute([$billId]);
        audit($u['name'], 'Collect', 'mall', $bill['shop'], "$receipt $amount via $method");
        json_out(['ok' => true, 'receipt' => $receipt]);
    }

    /* meter — record a sub-meter reading (elec/water); computes units from the previous
       reading and auto-generates the utility bill (custodial fund head). */
    if ($a === 'meter') {
        $shop = trim($body['shop'] ?? '');
        $type = trim($body['type'] ?? 'elec');
        if (!in_array($type, ['elec', 'water'], true)) json_out(['ok' => false, 'error' => 'type must be elec/water.'], 400);
        $reading = (int)($body['reading'] ?? 0);
        if (!$shop || $reading <= 0) json_out(['ok' => false, 'error' => 'shop and reading required.'], 400);
        $month = trim($body['month'] ?? date('Y-m'));
        $st = $pdo->prepare("SELECT reading FROM mall_meter_readings WHERE shop=? AND type=? AND month=? ORDER BY id DESC LIMIT 1");
        $st->execute([$shop, $type, $month]);
        $prev = (int)$st->fetchColumn();
        $units = $reading - $prev;
        if ($units < 0) json_out(['ok' => false, 'error' => 'Reading cannot be lower than the previous reading (' . $prev . ').'], 400);
        $pdo->prepare("INSERT INTO mall_meter_readings (shop, type, reading, units, month, note) VALUES (?,?,?,?,?,?)")
            ->execute([$shop, $type, $reading, $units, $month, trim($body['note'] ?? '')]);
        if ($units > 0) {
            $rate = (int)$mcfg($type === 'elec' ? 'elec_unit_rate' : 'water_unit_rate', $type === 'elec' ? '8' : '30');
            $amount = $units * $rate;
            $ex = $pdo->prepare("SELECT COUNT(*) FROM shop_bills WHERE shop=? AND month=? AND kind=?");
            $ex->execute([$shop, $month, $type]);
            if ((int)$ex->fetchColumn() === 0) {
                $dueDay = (int)$mcfg('due_day', '10');
                $pdo->prepare("INSERT INTO shop_bills (shop, month, kind, amount, fine, due_date, status)
                               VALUES (?,?,?,?,0,?,'Unpaid')")
                    ->execute([$shop, $month, $type, $amount, date('Y-m-d', strtotime($month . '-' . sprintf('%02d', $dueDay)))]);
            }
        }
        audit($u['name'], 'Meter', 'mall', $shop, "$type $reading ($units units)");
        json_out(['ok' => true, 'units' => $units]);
    }

    /* ledger — central: billed vs collected by kind; expenses; per-shop summary */
    if ($a === 'ledger') {
        $month = trim($body['month'] ?? date('Y-m'));
        $byKind = $pdo->prepare("SELECT kind,
                    COALESCE(SUM(CASE WHEN status='Paid' THEN amount ELSE 0 END),0) collected,
                    COALESCE(SUM(amount),0) billed
                    FROM shop_bills WHERE month=? GROUP BY kind");
        $byKind->execute([$month]);
        $exSt = $pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM company_ledger WHERE kind='expense' AND substr(ts,1,7)=?");
        $exSt->execute([$month]);
        $expenses = (int)$exSt->fetchColumn();
        $perShop = $pdo->prepare("SELECT s.id, s.no, s.floor, s.owner_name, s.owner_mobile,
                    COALESCE(SUM(CASE WHEN b.kind='service' AND b.status='Paid' THEN b.amount ELSE 0 END),0) sc_paid,
                    COALESCE(SUM(CASE WHEN b.kind='service' THEN b.amount ELSE 0 END),0) sc_billed,
                    COALESCE(SUM(CASE WHEN b.kind='elec' AND b.status='Paid' THEN b.amount ELSE 0 END),0) el_paid,
                    COALESCE(SUM(CASE WHEN b.kind='elec' THEN b.amount ELSE 0 END),0) el_billed,
                    COALESCE(SUM(CASE WHEN b.kind='water' AND b.status='Paid' THEN b.amount ELSE 0 END),0) w_paid,
                    COALESCE(SUM(CASE WHEN b.kind='water' THEN b.amount ELSE 0 END),0) w_billed
                    FROM shops s LEFT JOIN shop_bills b ON b.shop=s.id AND b.month=?
                    GROUP BY s.id ORDER BY s.floor, s.no");
        $perShop->execute([$month]);
        json_out(['ok' => true, 'month' => $month, 'by_kind' => $byKind->fetchAll(PDO::FETCH_ASSOC),
                  'expenses' => $expenses, 'per_shop' => $perShop->fetchAll(PDO::FETCH_ASSOC)]);
    }

    /* dashboard — committee overview: this-month KPIs, top defaulters, expense categories */
    if ($a === 'dashboard') {
        $month = trim($body['month'] ?? date('Y-m'));
        $kpi = $pdo->prepare("SELECT
                    COALESCE(SUM(CASE WHEN status='Paid' THEN amount ELSE 0 END),0) collected,
                    COALESCE(SUM(CASE WHEN status='Unpaid' THEN amount ELSE 0 END),0) outstanding,
                    COALESCE(SUM(amount),0) billed,
                    COUNT(CASE WHEN status='Unpaid' THEN 1 END) unpaid_bills
                    FROM shop_bills WHERE month=?");
        $kpi->execute([$month]);
        $defaulters = $pdo->prepare("SELECT s.id, s.no, s.floor, s.owner_name, s.owner_mobile,
                    COALESCE(SUM(b.amount),0) due FROM shops s JOIN shop_bills b ON b.shop=s.id
                    WHERE b.month=? AND b.status='Unpaid' GROUP BY s.id ORDER BY due DESC LIMIT 10");
        $defaulters->execute([$month]);
        $exC = $pdo->prepare("SELECT cat, COALESCE(SUM(amount),0) total FROM company_ledger
                    WHERE kind='expense' AND substr(ts,1,7)=? GROUP BY cat ORDER BY total DESC LIMIT 10");
        $exC->execute([$month]);
        $expCats = $exC->fetchAll(PDO::FETCH_ASSOC);
        $exT = $pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM company_ledger WHERE kind='expense' AND substr(ts,1,7)=?");
        $exT->execute([$month]);
        $expenseTotal = (int)$exT->fetchColumn();
        $shopCount = (int)$pdo->query("SELECT COUNT(*) FROM shops")->fetchColumn();
        $activeShops = (int)$pdo->query("SELECT COUNT(*) FROM shops WHERE status='Active'")->fetchColumn();
        json_out(['ok' => true, 'month' => $month, 'kpi' => $kpi->fetch(PDO::FETCH_ASSOC),
                  'defaulters' => $defaulters->fetchAll(PDO::FETCH_ASSOC),
                  'expense_cats' => $expCats, 'expense_total' => $expenseTotal, 'shops' => ['total' => $shopCount, 'active' => $activeShops]]);
    }

    json_out(['ok' => false, 'error' => "Unknown mall action '$a'."], 400);
}

case 'app-crud': {
    $u = require_user();
    $action = $body['action'] ?? '';
    $collection = $body['collection'] ?? '';
    $fields = CRUD_FIELDS()[$collection] ?? null;
    if (!in_array($action, ['create', 'update', 'delete'], true)) json_out(['ok' => false, 'error' => 'Invalid action.'], 400);
    if (!$fields) json_out(['ok' => false, 'error' => 'Unknown collection.'], 400);
    if (!can_crud($u['role'], $collection)) json_out(['ok' => false, 'error' => "Access denied — CRUD on $collection for {$u['role']}."], 403);
    /* Phase 6: row-scope guard — tenant/partner may only touch their own rows */
    if ($u['role'] === 'tenant' && $action !== 'create') {
        json_out(['ok' => false, 'error' => 'Tenants cannot edit records.'], 403);
    }
    if ($u['role'] === 'partner' && $collection !== 'tickets') {
        json_out(['ok' => false, 'error' => 'Partners can only work with their jobs.'], 403);
    }
    $pdo = db();
    $data = array_intersect_key($body['data'] ?? [], array_flip($fields));
    $id = trim($body['id'] ?? '');
    /* SA1 v18: subscribers can never set ownership directly — create enforcement stamps it,
       update path strips it (prevents reassigning a property/unit to another account). */
    if (($u['kind'] ?? '') === 'sub') unset($data['sub_email']);

    if ($action === 'delete') {
        if (in_array($u['role'], ['tenant', 'partner'], true)) json_out(['ok' => false, 'error' => 'Not allowed to delete.'], 403);
        if (!$id) json_out(['ok' => false, 'error' => 'id required.'], 400);
        crud_guard_owner($pdo, $u, $collection, $id);
        $pdo->prepare("DELETE FROM $collection WHERE id=?")->execute([$id]);
        audit($u['name'], 'Deleted', $collection, $id);
        json_out(['ok' => true]);
    }

    /* create */
    if ($action === 'create') {
        $prefix = CRUD_PREFIX()[$collection] ?? '';
        if ($collection === 'invoices') {
            $id = invoice_next_id($pdo);
        } else {
            $pad = $collection === 'partners' || $collection === 'staff' ? 2 : 3;
            $id = next_id($collection, $prefix, $pad);
        }
        /* tenant can only create tickets for their own units */
        if ($u['role'] === 'tenant' && $collection === 'tickets') {
            $mine = my_units($u);
            if (!$mine || !in_array($data['u'] ?? '', $mine, true)) {
                json_out(['ok' => false, 'error' => 'You can only raise tickets for your own unit.'], 403);
            }
            $data['status'] = 'Open';
        }
        /* partner creates nothing */
        if ($u['role'] === 'partner') json_out(['ok' => false, 'error' => 'Partners cannot create records.'], 403);
        /* leases: default status by registration rule */
        if ($collection === 'leases' && empty($data['status'])) {
            $data['status'] = (($data['res'] ?? 1) == 0 && empty($data['reg_office'])) ? 'Pending Registration' : 'Active';
        }
        /* invoices: derive net if not provided */
        if ($collection === 'invoices' && empty($data['net'])) {
            $data['net'] = (int)($data['gross'] ?? 0) - (int)($data['tds'] ?? 0);
        }
        if (empty($data)) json_out(['ok' => false, 'error' => 'No valid fields.'], 400);
        /* SA1 v18: enforce per-subscriber plan limits (property_limit / unit_limit) on create.
           Staff (superadmin/manager/etc.) are unlimited; subscribers are counted by sub_email.
           SA1 v25.6: tenants stamped too — without sub_email the row-ownership guard treats
           the row as shared and a second subscriber could edit/delete it (real IDOR found). */
        if (($u['kind'] ?? '') === 'sub' && in_array($collection, ['properties', 'units', 'tenants'], true)) {
            $email = strtolower(trim($u['email']));
            $lim = effective_limits($u);
            if ($collection === 'properties') {
                $cnt = (int)$pdo->query('SELECT COUNT(*) FROM properties WHERE sub_email=' . $pdo->quote($email))->fetchColumn();
                if ($cnt >= (int)($lim['property_limit'] ?? 9999)) {
                    json_out(['ok' => false, 'error' => "Plan limit reached: $cnt of {$lim['property_limit']} properties. Upgrade to lift limits."], 403);
                }
                $data['sub_email'] = $email;
            } elseif ($collection === 'units') {
                $pid = $data['p'] ?? '';
                $own = '';
                if ($pid !== '') {
                    $st = $pdo->prepare('SELECT sub_email FROM properties WHERE id=?'); $st->execute([$pid]);
                    $own = (string)$st->fetchColumn();
                }
                if ($own !== '' && strtolower(trim($own)) !== $email) {
                    json_out(['ok' => false, 'error' => 'This property belongs to another account.'], 403);
                }
                $cnt = (int)$pdo->query('SELECT COUNT(*) FROM units WHERE sub_email=' . $pdo->quote($email))->fetchColumn();
                if ($cnt >= (int)($lim['unit_limit'] ?? 99999)) {
                    json_out(['ok' => false, 'error' => "Plan limit reached: $cnt of {$lim['unit_limit']} units. Upgrade to lift limits."], 403);
                }
                $data['sub_email'] = $email;
            } else {   /* tenants — stamp ownership only (no plan limit) */
                $data['sub_email'] = $email;
            }
        }
        $keys = array_keys($data);
        $pdo->prepare('INSERT INTO ' . $collection . ' (id, ' . implode(',', $keys) . ') VALUES (?, ' . implode(',', array_fill(0, count($keys), '?')) . ')')
            ->execute(array_merge([$id], array_values($data)));
        audit($u['name'], 'Created', $collection, $id);
        $provision = [];
        /* V2.38: tenants auto-get a NID verification record so they appear in 🪪 NID & Trust */
        if ($collection === 'tenants') {
            nid_ensure_for_tenant($pdo, $id, $data['nid'] ?? '', '', $u['name']);
            /* V2.39: a tenant with an email gets a portal login account + welcome email */
            if (trim((string)($data['email'] ?? '')) !== '') {
                $provision = tenant_provision_account($pdo, $id, $u['name']);
            }
        }
        json_out(['ok' => true, 'id' => $id, 'provision' => $provision]);
    }

    /* update */
    if ($u['role'] === 'tenant') json_out(['ok' => false, 'error' => 'Tenants cannot edit records.'], 403);
    if ($u['role'] === 'partner') {
        $st = $pdo->prepare('SELECT con FROM tickets WHERE id=?'); $st->execute([$id]);
        $con = $st->fetchColumn();
        if ($con !== '' && $con !== my_org($u)) json_out(['ok' => false, 'error' => 'You can only update your own jobs.'], 403);
        if (empty($data['con'])) $data['con'] = my_org($u);   /* quoting an open job assigns it */
    }
    if (!$id) json_out(['ok' => false, 'error' => 'id required.'], 400);
    if (empty($data)) json_out(['ok' => false, 'error' => 'No valid fields.'], 400);
    crud_guard_owner($pdo, $u, $collection, $id);
    if ($collection === 'invoices' && empty($data['net'])) {
        /* BUGFIX: only re-derive net when gross/tds are actually being changed; a status-only
           edit (e.g. mark Overdue) must not zero net → invoices looked "fully paid". */
        if (isset($data['gross']) || isset($data['tds'])) {
            $cur = null;
            $st = $pdo->prepare('SELECT gross, tds FROM invoices WHERE id=?'); $st->execute([$id]);
            $cur = $st->fetch(PDO::FETCH_ASSOC);
            $g = isset($data['gross']) ? (int)$data['gross'] : (int)($cur['gross'] ?? 0);
            $t = isset($data['tds'])   ? (int)$data['tds']   : (int)($cur['tds'] ?? 0);
            $data['net'] = $g - $t;
        }
    }
    $sets = implode(',', array_map(fn($k) => "$k=?", array_keys($data)));
    $pdo->prepare('UPDATE ' . $collection . " SET $sets WHERE id=?")->execute(array_merge(array_values($data), [$id]));
    audit($u['name'], 'Updated', $collection, $id, json_encode($data) ?: '');
    $provision = [];
    /* V2.38: keep NID verification in sync when a tenant's NID is edited */
    if ($collection === 'tenants') {
        if (isset($data['nid'])) nid_ensure_for_tenant($pdo, $id, $data['nid'], '', $u['name']);
        /* V2.39: when an email is added to a tenant, provision the portal account + welcome email */
        if (isset($data['email']) && trim((string)$data['email']) !== '') {
            $provision = tenant_provision_account($pdo, $id, $u['name']);
        }
    }
    json_out(['ok' => true, 'id' => $id, 'provision' => $provision]);
}

case 'app-profile': {
    /* Phase 18 unified: GET → profile+settings; POST → update fields and/or change password */
    $u = require_user();
    $pdo = db();
    if ($_SERVER['REQUEST_METHOD'] === 'GET' || empty($body)) {
        json_out(['ok' => true, 'profile' => user_profile($pdo, $u), 'user' => user_payload($u)]);
    }
    $table = $u['kind'] === 'sub' ? 'subscribers' : 'app_users';
    $uid = $u['id'];
    $tok_kind = $u['kind'];
    if (!empty($u['team_member'])) {          /* SA1 v20: members update their OWN row, not the owner's */
        $table = 'team_members'; $uid = $u['team_id']; $tok_kind = 'team';
    }
    $sets = []; $args = []; $changed = [];
    if (isset($body['name']) && trim($body['name']) !== '') {
        $sets[] = 'name=?'; $args[] = trim($body['name']); $changed[] = 'name';
    }
    if ($u['kind'] === 'sub' && empty($u['team_member'])) {
        if (isset($body['org'])) { $sets[] = 'org=?'; $args[] = trim($body['org']); $changed[] = 'org'; }
        if (isset($body['phone'])) { $sets[] = 'phone=?'; $args[] = trim($body['phone']); $changed[] = 'phone'; }
    } elseif (!empty($u['team_member'])) {
        /* team members: name + password only (no org/phone columns) */
    } else {
        if (isset($body['dept'])) { $sets[] = 'dept=?'; $args[] = trim($body['dept']); $changed[] = 'dept'; }
        if (isset($body['avatar'])) { $sets[] = 'avatar=?'; $args[] = trim(substr($body['avatar'], 0, 8)); $changed[] = 'avatar'; }
    }
    if (isset($body['new_password']) && $body['new_password'] !== '') {
        $old = $body['old_password'] ?? '';
        $new = $body['new_password'];
        if (strlen($new) < (int)admin_cfg(db(), 'password_min', 8)) json_out(['ok' => false, 'error' => 'New password must be at least ' . (int)admin_cfg(db(), 'password_min', 8) . ' characters.'], 400);
        $perr = password_policy_error($pdo, $new);
        if ($perr !== '') json_out(['ok' => false, 'error' => $perr], 400);
        if (!$old) json_out(['ok' => false, 'error' => 'Current password is required to change it.'], 400);
        $st = $pdo->prepare("SELECT password_hash FROM $table WHERE id=?"); $st->execute([$uid]);
        $hash = $st->fetchColumn();
        if (!$hash || !password_verify($old, $hash)) {
            record_attempt($u['email'], client_ip(), 'profile-pw', false);
            json_out(['ok' => false, 'error' => 'Current password is incorrect.'], 403);
        }
        $sets[] = 'password_hash=?'; $args[] = password_hash($new, PASSWORD_DEFAULT); $changed[] = 'password';
        /* invalidate other sessions so the new password is enforced everywhere */
        $pdo->prepare("DELETE FROM app_tokens WHERE user_id=? AND kind=?")->execute([$uid, $tok_kind]);
    }
    if (!$sets) json_out(['ok' => false, 'error' => 'Nothing to update.'], 400);
    $args[] = $uid;
    $pdo->prepare("UPDATE $table SET " . implode(',', $sets) . " WHERE id=?")->execute($args);
    /* keep tenant row in sync when a linked subscriber updates name/phone (owner only, not team members) */
    if (($u['kind'] === 'sub') && empty($u['team_member']) && (in_array('name', $changed, true) || in_array('phone', $changed, true))) {
        $tid = tenant_resolve_id($pdo, $u['email']);
        if ($tid) {
            $tsets = []; $targs = [];
            if (in_array('name', $changed, true)) { $tsets[] = 'name=?'; $targs[] = trim($body['name']); }
            if (in_array('phone', $changed, true)) { $tsets[] = 'phone=?'; $targs[] = trim($body['phone']); }
            if ($tsets) { $targs[] = $tid; $pdo->prepare('UPDATE tenants SET ' . implode(',', $tsets) . ' WHERE id=?')->execute($targs); }
        }
    }
    audit($u['name'], 'Profile updated', 'auth', (string)$u['id'], implode(',', $changed));
    $pwChanged = in_array('password', $changed, true);
    $u2 = $pwChanged ? null : current_user();
    $fresh = null;
    if ($u2) {
        $st = $pdo->prepare("SELECT * FROM $table WHERE id=?"); $st->execute([$u['id']]);
        $fr = $st->fetch(PDO::FETCH_ASSOC); $fr['kind'] = $u['kind'];
        $fresh = user_profile($pdo, $fr);
    }
    json_out(['ok' => true, 'updated' => $changed, 'sessions_invalidated' => $pwChanged,
              'user' => $u2 ? user_payload($u2) : null, 'profile' => $fresh]);
}

case 'app-health': {
